-- Generated by tools/build_quest_data.py; references are not eligibility or a walkthrough.
return {["scripts/quests/windurst/Curses_Foiled_A_Golem.lua"]={["Path"]="scripts/quests/windurst/Curses_Foiled_A_Golem.lua",["SHA256"]="bde6826fef0b10919e833f1582eff32ad1e138bc6cb2dfdd09c8289d4d37f6d6",["Text"]="-----------------------------------\n-- Curses, Foiled A-Golem!?\n-----------------------------------\n-- !addquest 2 63\n-- Shantotto       : !pos 122 -2 112 239\n-- Torino-Samarino : !pos 105 -20 140 111\n-- Cermet Door     : !pos -183 0 190 204\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.WINDURST, xi.quest.id.windurst.CURSES_FOILED_A_GOLEM)\n\nquest.reward =\n{\n    fame     = 40,\n    fameArea = xi.fameArea.WINDURST,\n    item     = xi.item.SCROLL_OF_WARP_II,\n    title    = xi.title.DOCTOR_SHANTOTTOS_FLAVOR_OF_THE_MONTH,\n}\n\n-- Block used by mobs which can remove \"Shantotto's New Spell\" key item.  This needs\n-- verification regarding it being all mobs or if limited to current implementation,\n-- and also if there is a chance or limit for kills before removal.\nlocal feiyinMob =\n{\n    onMobDeath = function(mob, player, optParams)\n        if player:hasKeyItem(xi.keyItem.SHANTOTTOS_NEW_SPELL) then\n            player:delKeyItem(xi.keyItem.SHANTOTTOS_NEW_SPELL)\n            npcUtil.giveKeyItem(player, xi.keyItem.SHANTOTTOS_EX_SPELL)\n        end\n    end,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.WINDURST, xi.quest.id.windurst.CURSES_FOILED_AGAIN_2) and\n                player:getFameLevel(xi.fameArea.WINDURST) >= 4 and\n                player:getMainLvl() >= 10 and\n                not quest:getMustZone(player)\n        end,\n\n        [xi.zone.WINDURST_WALLS] =\n        {\n            ['Shantotto'] = quest:progressEvent(340),\n\n            onEventFinish =\n            {\n                [340] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:begin(player)\n                    else\n                        player:setTitle(xi.title.TOTAL_LOSER)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        ['Leigon-Moigon'] =\n        {\n            onTrigger = function(player, npc)\n                if player:hasKeyItem(xi.keyItem.SHANTOTTOS_NEW_SPELL) then\n                    return quest:event(107)\n                elseif quest:getVar(player, 'Prog') == 2 then\n                    return quest:event(112)\n                end\n            end,\n        },\n\n        ['Potete'] =\n        {\n            onTrigger = function(player, npc)\n                if player:hasKeyItem(xi.keyItem.SHANTOTTOS_NEW_SPELL) then\n                    return quest:event(106)\n                elseif quest:getVar(player, 'Prog') == 2 then\n                    return quest:event(111)\n                end\n            end,\n        },\n\n        [xi.zone.BEAUCEDINE_GLACIER] =\n        {\n            ['Torino-Samarino'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 0 then\n                        return quest:progressEvent(104)\n                    elseif questProgress == 1 then\n                        if player:hasKeyItem(xi.keyItem.SHANTOTTOS_NEW_SPELL) then\n                            return quest:event(105)\n                        elseif player:hasKeyItem(xi.keyItem.SHANTOTTOS_EX_SPELL) then\n                            return quest:progressEvent(108)\n                        else\n                            if quest:getVar(player, 'Timer') <= VanadielUniqueDay() then\n                                return quest:progressEvent(109)\n                            else\n                                return quest:event(113)\n                            end\n                        end\n                    elseif questProgress == 2 then\n                        return quest:event(110)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [104] = function(player, csid, option, npc)\n                    if option == 1 then\n                        npcUtil.giveKeyItem(player, xi.keyItem.SHANTOTTOS_NEW_SPELL)\n                        quest:setVar(player, 'Prog', 1)\n                    end\n                end,\n\n                [108] = function(player, csid, option, npc)\n                    player:delKeyItem(xi.keyItem.SHANTOTTOS_EX_SPELL)\n                    quest:setVar(player, 'Timer', VanadielUniqueDay() + 1)\n                end,\n\n                [109] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.SHANTOTTOS_NEW_SPELL)\n                end,\n            },\n        },\n\n        [xi.zone.FEIYIN] =\n        {\n            ['_no4'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.SHANTOTTOS_NEW_SPELL) then\n                        return quest:progressEvent(14)\n                    elseif player:hasKeyItem(xi.keyItem.SHANTOTTOS_EX_SPELL) then\n                        return quest:event(13)\n                    end\n                end,\n            },\n\n            ['Clockwork_Pod'] = feiyinMob,\n            ['Colossus']      = feiyinMob,\n            ['Droma']         = feiyinMob,\n            ['Drone']         = feiyinMob,\n            ['Jenglot']       = feiyinMob,\n            ['Mind_Hoarder']  = feiyinMob,\n            ['Ore_Golem']     = feiyinMob,\n            ['Talos']         = feiyinMob,\n\n            onEventFinish =\n            {\n                [14] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                    player:delKeyItem(xi.keyItem.SHANTOTTOS_NEW_SPELL)\n                end,\n            },\n        },\n\n        [xi.zone.WINDURST_WALLS] =\n        {\n            ['Shantotto'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 2 then\n                        return quest:progressEvent(342)\n                    else\n                        return quest:event(341)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [342] = function(player, csid, option, npc)\n                    -- Per FFXIclopedia: You can still get [Total Loser] at the\n                    -- title-changing NPC after the quest has been completed.\n                    player:addTitle(xi.title.TOTAL_LOSER)\n                    quest:complete(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.WINDURST_WALLS] =\n        {\n            ['Shantotto'] = quest:event(343):replaceDefault(),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/windurst/Curses_Foiled_Again_1.lua"]={["Path"]="scripts/quests/windurst/Curses_Foiled_Again_1.lua",["SHA256"]="ce2686e98595cc4fccd816c0b82003212cb8235121d10f3316adb19432a81a63",["Text"]="-----------------------------------\n-- Curses, Foiled Again! (1)\n-----------------------------------\n-- !addquest 2 32\n-- Shantotto : !pos 122 -2 112 239\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.WINDURST, xi.quest.id.windurst.CURSES_FOILED_AGAIN_1)\n\nquest.reward =\n{\n    fame     = 20,\n    fameArea = xi.fameArea.WINDURST,\n    item     = xi.item.BRASS_ROD,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.WINDURST_WALLS] =\n        {\n            ['Shantotto'] = quest:event(171, 0, 0, 0, 0, 0, 0, xi.item.PINCH_OF_BOMB_ASH, xi.item.BONE_CHIP),\n\n            onEventFinish =\n            {\n                [171] = function(player, csid, option, npc)\n                    if option == 3 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        }\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.WINDURST_WALLS] =\n        {\n            ['Shantotto'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, { xi.item.PINCH_OF_BOMB_ASH, { xi.item.BONE_CHIP, 2 } }) then\n                        return quest:progressEvent(173, 0, 0, 0, 0, 0, 0, xi.item.PINCH_OF_BOMB_ASH, xi.item.BONE_CHIP)\n                    end\n                end,\n\n                onTrigger = quest:event(172, 0, 0, 0, 0, 0, 0, xi.item.PINCH_OF_BOMB_ASH, xi.item.BONE_CHIP)\n            },\n\n            onEventFinish =\n            {\n                [173] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:confirmTrade()\n\n                        xi.quest.setVar(player, xi.questLog.WINDURST, xi.quest.id.windurst.CURSES_FOILED_AGAIN_2, 'Timer', VanadielUniqueDay() + 1)\n\n                        -- NOTE: There's two zoning mechanics required prior to the next quest being displayed in logs.  To make this easier,\n                        -- setting a mustZone value for this quest as a requisite in order to utilize mustZone in the next quest's available\n                        -- block.\n                        xi.quest.setMustZone(player, xi.questLog.WINDURST, xi.quest.id.windurst.CURSES_FOILED_AGAIN_1)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/windurst/Curses_Foiled_Again_2.lua"]={["Path"]="scripts/quests/windurst/Curses_Foiled_Again_2.lua",["SHA256"]="1006d48ae31f4a6c6d7dc058f17462567c64813bbab4526ff27eb7ed7bebbe86",["Text"]="-----------------------------------\n-- Curses, Foiled Again!? (2)\n-----------------------------------\n-- !addquest 2 33\n-- Shantotto : !pos 122 -2 112 239\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.WINDURST, xi.quest.id.windurst.CURSES_FOILED_AGAIN_2)\n\nquest.reward =\n{\n    fame     = 20,\n    fameArea = xi.fameArea.WINDURST,\n    item     = xi.item.MISERY_STAFF,\n    title    = xi.title.HEXER_VEXER,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.WINDURST, xi.quest.id.windurst.CURSES_FOILED_AGAIN_1) and\n                player:getFameLevel(xi.fameArea.WINDURST) >= 2\n        end,\n\n        [xi.zone.WINDURST_WALLS] =\n        {\n            ['Shantotto'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        quest:getVar(player, 'Timer') <= VanadielUniqueDay() and\n                        not xi.quest.getMustZone(player, xi.questLog.WINDURST, xi.quest.id.windurst.CURSES_FOILED_AGAIN_1)\n                    then\n                        local questProgress = quest:getVar(player, 'Prog')\n\n                        if questProgress == 0 then\n                            return quest:event(178)\n                        elseif questProgress == 1 then\n                            return quest:event(177)\n                        elseif\n                            questProgress == 2 and\n                            not quest:getMustZone(player)\n                        then\n                            return quest:progressEvent(180, 0, 0, 0, 0, xi.item.PINCH_OF_BOMB_ASH, xi.item.BONE_CHIP, xi.item.BOMB_ARM, xi.item.REVIVAL_TREE_ROOT)\n                        end\n                    else\n                        return quest:event(174)\n                    end\n                end,\n            },\n\n            ['Hiwon-Biwon'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        quest:getVar(player, 'Timer') <= VanadielUniqueDay() and\n                        not xi.quest.getMustZone(player, xi.questLog.WINDURST, xi.quest.id.windurst.CURSES_FOILED_AGAIN_1)\n                    then\n                        -- NOTE: There is interplay between Making Headlines and this quest for dialogue.  We should be safe with\n                        -- fallthroughs in interaction, but also there may be a better method to implement both.\n\n                        if player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.MAKING_HEADLINES) == xi.questStatus.QUEST_ACCEPTED then\n                            return quest:progressEvent(284)\n                        else\n                            return quest:progressEvent(179)\n                        end\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [177] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                    quest:setMustZone(player)\n                end,\n\n                [179] = function(player, csid, option, npc)\n                    if quest:getVar(player, 'Prog') == 0 then\n                        quest:setVar(player, 'Prog', 1)\n                    end\n                end,\n\n                [180] = function(player, csid, option, npc)\n                    if option == 3 then\n                        quest:begin(player)\n                        player:setTitle(xi.title.TARUTARU_MURDER_SUSPECT)\n                    end\n                end,\n\n                [284] = function(player, csid, option, npc)\n                    if quest:getVar(player, 'Prog') == 0 then\n                        quest:setVar(player, 'Prog', 1)\n                    end\n                end,\n            },\n        }\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.WINDURST_WALLS] =\n        {\n            ['Shantotto'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, { { xi.item.BOMB_ARM, 2 }, xi.item.REVIVAL_TREE_ROOT, xi.item.LOCK_OF_HIWONS_HAIR }) then\n                        return quest:progressEvent(183, 0, 0, 0, 0, 0, 0, xi.item.BOMB_ARM, xi.item.REVIVAL_TREE_ROOT)\n                    end\n                end,\n\n                onTrigger = quest:event(181, 0, 0, 0, 0, 0, 0, xi.item.BOMB_ARM, xi.item.REVIVAL_TREE_ROOT),\n            },\n\n            ['Hiwon-Biwon'] = quest:progressEvent(182),\n\n            onEventFinish =\n            {\n                [182] = function(player, csid, option, npc)\n                    -- NOTE: This event is blocking, and always attempts to give to player, even\n                    -- if one is currently in inventory.\n\n                    npcUtil.giveItem(player, xi.item.LOCK_OF_HIWONS_HAIR)\n                end,\n\n                [183] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:confirmTrade()\n\n                        xi.quest.setMustZone(player, xi.questLog.WINDURST, xi.quest.id.windurst.CURSES_FOILED_A_GOLEM)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED and\n                not player:hasCompletedQuest(xi.questLog.WINDURST, xi.quest.id.windurst.CURSES_FOILED_A_GOLEM)\n        end,\n\n        [xi.zone.WINDURST_WALLS] =\n        {\n            ['Hiwon-Biwon'] = quest:event(185):replaceDefault(),\n            ['Shantotto']   = quest:event(184):replaceDefault(),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/windurst/Early_Bird_Catches_the_Bookworm.lua"]={["Path"]="scripts/quests/windurst/Early_Bird_Catches_the_Bookworm.lua",["SHA256"]="bc70ffd59340b893e6b0daa36fbfb97923f0272fa651882dd4997e9bab0ad8e6",["Text"]="-----------------------------------\n-- Early Bird Catches the Bookworm\n-----------------------------------\n-- !addquest 2 20\n-- Tosuka-Porika   : !pos -26 -6 103 238\n-- Furakku-Norakku : !pos -19 -5 101 238\n-- Orn             : !pos -68 -9 30 238\n-- Quu Bokye       : !pos -159 16 181 145\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.WINDURST, xi.quest.id.windurst.EARLY_BIRD_CATCHES_THE_BOOKWORM)\n\nquest.reward =\n{\n    fame = 20,\n    fameArea = xi.fameArea.WINDURST,\n    gil = 1500,\n    title = xi.title.SAVIOR_OF_KNOWLEDGE,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.WINDURST, xi.quest.id.windurst.GLYPH_HANGER) and\n                player:getFameLevel(xi.fameArea.WINDURST) >= 2 and\n                not quest:getMustZone(player)\n        end,\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n            ['Tosuka-Porika'] =\n            {\n                onTrigger = function(player, npc)\n                    -- TODO: Requirements for availability need to be verified, and was referenced at the below location.  Left\n                    -- in this block to make it easier to remove if it turns out to be inaccurate.\n                    -- https://ffxiclopedia.fandom.com/wiki/Early_Bird_Catches_the_Bookworm\n                    if\n                        player:getNation() ~= xi.nation.WINDURST or\n                        (player:getCurrentMission(xi.mission.log_id.WINDURST) ~= xi.mission.id.windurst.LOST_FOR_WORDS and\n                        player:getCurrentMission(xi.mission.log_id.WINDURST) ~= xi.mission.id.windurst.THE_SIXTH_MINISTRY)\n                    then\n                        return quest:progressEvent(387)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [387] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n            ['Furakku-Norakku'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 0 then\n                        if not player:hasKeyItem(xi.keyItem.OVERDUE_BOOK_NOTIFICATIONS_EARLY_BIRD) then\n                            return quest:progressEvent(389, 0, xi.keyItem.ART_FOR_EVERYONE)\n                        else\n                            return quest:progressEvent(390, 0, xi.keyItem.ART_FOR_EVERYONE)\n                        end\n                    elseif questProgress == 1 then\n                        return quest:progressEvent(397, 0, xi.keyItem.ART_FOR_EVERYONE)\n                    elseif questProgress >= 2 then\n                        return quest:progressEvent(400)\n                    end\n                end,\n            },\n\n            ['Orn'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if\n                        questProgress == 0 and\n                        player:hasKeyItem(xi.keyItem.OVERDUE_BOOK_NOTIFICATIONS_EARLY_BIRD)\n                    then\n                        return quest:progressEvent(395, 0, xi.keyItem.ART_FOR_EVERYONE)\n                    elseif questProgress == 1 then\n                        return quest:progressEvent(396)\n                    elseif questProgress == 2 then\n                        return quest:progressEvent(398)\n                    elseif questProgress == 3 then\n                        return quest:progressEvent(399)\n                    end\n                end,\n            },\n\n            ['Tosuka-Porika'] = quest:progressEvent(388),\n\n            onEventFinish =\n            {\n                [389] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.OVERDUE_BOOK_NOTIFICATIONS_EARLY_BIRD)\n                end,\n\n                [395] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                    player:delKeyItem(xi.keyItem.OVERDUE_BOOK_NOTIFICATIONS_EARLY_BIRD)\n                end,\n\n                [398] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 3)\n                end,\n\n                [400] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:setLocalVar('Quest[2][13]mustZone', 1)\n                        player:delKeyItem(xi.keyItem.ART_FOR_EVERYONE)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.GIDDEUS] =\n        {\n            ['Quu_Bokye'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        quest:getVar(player, 'Prog') == 1 and\n                        npcUtil.tradeHasExactly(trade, xi.item.SILVER_BEASTCOIN)\n                    then\n                        return quest:progressEvent(58)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 1 then\n                        return quest:progressEvent(57)\n                    elseif questProgress == 2 then\n                        return quest:progressEvent(59)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [58] = function(player, csid, option, npc)\n                    player:confirmTrade()\n                    npcUtil.giveKeyItem(player, xi.keyItem.ART_FOR_EVERYONE)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED and\n                player:getLocalVar('Quest[2][13]mustZone') == 1\n        end,\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n            ['Furakku-Norakku'] = quest:event(401):replaceDefault()\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/windurst/Eco_Warrior.lua"]={["Path"]="scripts/quests/windurst/Eco_Warrior.lua",["SHA256"]="0101effcd6d5d145d8a1b0e1db84edf49edd7ce755eef0779c0ad0c64c3f0813",["Text"]="-----------------------------------\n-- Eco-Warrior (Windurst)\n-----------------------------------\n-- Log ID: 2, Quest ID: 84\n-- !addquest 2 84\n-- Lumomo            : !pos -55.770 -5.499 18.914 238\n-- Ahko Mhalijikhari : !pos -344.617 -12.226 -166.233 198\n-- qm2               : !pos 143 9 -219 198\n-----------------------------------\n-- The indigested meat alone gates the turn-in. Returning to Ahko Mhalijikhari first is optional.\n-- Event 65 does not remove the level restriction. Removal stays available through event 64.\n-- Completing any nation's Eco-Warrior locks all three until the next conquest tally.\n-----------------------------------\nlocal mazeID = zones[xi.zone.MAZE_OF_SHAKHRAMI]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.WINDURST, xi.quest.id.windurst.ECO_WARRIOR)\n\nquest.reward =\n{\n    fame     = 20,\n    fameArea = xi.fameArea.WINDURST,\n    gil      = 5000,\n    item     = xi.item.DRAGON_CHRONICLES,\n    title    = xi.title.EMERALD_EXTERMINATOR,\n}\n\nquest.sections =\n{\n    -- Section: Quest is available.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n            ['Lumomo'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.ECO_WARRIOR) == xi.questStatus.QUEST_ACCEPTED or\n                        player:getQuestStatus(xi.questLog.BASTOK, xi.quest.id.bastok.ECO_WARRIOR) == xi.questStatus.QUEST_ACCEPTED\n                    then\n                        return quest:event(823) -- Already on another nation's Eco-Warrior.\n                    elseif\n                        player:getFameLevel(xi.fameArea.WINDURST) >= 1 and\n                        player:getCharVar('EcoReset') == 0\n                    then\n                        return quest:progressEvent(818) -- Offers the quest.\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [818] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest accepted.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.MAZE_OF_SHAKHRAMI] =\n        {\n            ['Ahko_Mhalijikhari'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        player:hasKeyItem(xi.keyItem.INDIGESTED_MEAT) and\n                        quest:getVar(player, 'Informed') == 0\n                    then\n                        return quest:progressEvent(65) -- Sends the player to Lumomo.\n                    elseif player:hasStatusEffect(xi.effect.LEVEL_RESTRICTION) then\n                        return quest:progressEvent(64) -- Offers to remove the ointment.\n                    elseif not player:hasKeyItem(xi.keyItem.INDIGESTED_MEAT) then\n                        return quest:progressEvent(62) -- Offers to apply the ointment.\n                    end\n                end,\n            },\n\n            ['qm2'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        quest:getVar(player, 'Prog') == 0 and\n                        player:hasStatusEffect(xi.effect.LEVEL_RESTRICTION) and\n                        npcUtil.popFromQM(player, npc, { mazeID.mob.WYRMFLY_OFFSET, mazeID.mob.WYRMFLY_OFFSET + 1, mazeID.mob.WYRMFLY_OFFSET + 2 }, { claim = true, look = true, hide = 0 })\n                    then\n                        return quest:messageSpecial(mazeID.text.OINTMENT_DRAWS_MONSTERS)\n                    elseif\n                        quest:getVar(player, 'Prog') == 1 and\n                        not player:hasKeyItem(xi.keyItem.INDIGESTED_MEAT)\n                    then\n                        return quest:keyItem(xi.keyItem.INDIGESTED_MEAT)\n                    end\n                end,\n            },\n\n            ['Wyrmfly'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    if not player:hasStatusEffect(xi.effect.LEVEL_RESTRICTION) then\n                        return\n                    end\n\n                    for i = mazeID.mob.WYRMFLY_OFFSET, mazeID.mob.WYRMFLY_OFFSET + 2 do\n                        local nmCheck = GetMobByID(i)\n\n                        if\n                            i ~= mob:getID() and\n                            nmCheck and\n                            nmCheck:isAlive()\n                        then\n                            return\n                        end\n                    end\n\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [62] = function(player, csid, option, npc)\n                    if option == 1 then\n                        player:addStatusEffect(xi.effect.LEVEL_RESTRICTION, {\n                            power    = 25,\n                            subPower = 1, -- exp uses actual level and not the restricted level.\n                            origin   = player,\n                            flag     = xi.effectFlag.ON_ZONE\n                        })\n                    end\n                end,\n\n                [64] = function(player, csid, option, npc)\n                    if option == 0 then\n                        player:delStatusEffect(xi.effect.LEVEL_RESTRICTION)\n                    end\n                end,\n\n                [65] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:setVar(player, 'Informed', 1)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n            ['Lumomo'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.INDIGESTED_MEAT) then\n                        return quest:progressEvent(822) -- Completes the quest.\n                    else\n                        return quest:event(820) -- Reminder to see Ahko Mhalijikhari.\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [822] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.INDIGESTED_MEAT)\n                        player:setCharVar('EcoReset', 1, NextConquestTally())\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest completed.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n            ['Lumomo'] =\n            {\n                onTrigger = function(player, npc)\n                    -- Repeatable after the next conquest tally.\n                    if\n                        player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.ECO_WARRIOR) == xi.questStatus.QUEST_ACCEPTED or\n                        player:getQuestStatus(xi.questLog.BASTOK, xi.quest.id.bastok.ECO_WARRIOR) == xi.questStatus.QUEST_ACCEPTED\n                    then\n                        return quest:event(823) -- Already on another nation's Eco-Warrior.\n                    elseif\n                        player:getFameLevel(xi.fameArea.WINDURST) >= 1 and\n                        player:getCharVar('EcoReset') == 0\n                    then\n                        return quest:progressEvent(818) -- Offers the quest.\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [818] = function(player, csid, option, npc)\n                    if option == 1 then\n                        player:delQuest(xi.questLog.WINDURST, xi.quest.id.windurst.ECO_WARRIOR)\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/windurst/Flower_Child.lua"]={["Path"]="scripts/quests/windurst/Flower_Child.lua",["SHA256"]="5c2081ede62b0afae65252b4c9b8f29b48b518a8074d4205540e8dbfbcdaa0bd",["Text"]="-----------------------------------\n-- Flower Child\n-----------------------------------\n-- Log ID: 2, Quest ID: 65\n-- Ojha Rhawash : !pos -209 0 -134 239\n-----------------------------------\nlocal windurstWallsID = zones[xi.zone.WINDURST_WALLS]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.WINDURST, xi.quest.id.windurst.FLOWER_CHILD)\n\nquest.reward =\n{\n    fame     = 0,\n    fameArea = xi.fameArea.WINDURST,\n}\n\nlocal flowerItems =\n{\n    xi.item.AMARYLLIS,\n    xi.item.ASPHODEL,\n    xi.item.CARNATION,\n    xi.item.CASABLANCA,\n    xi.item.CATTLEYA,\n    xi.item.CHAMOMILE,\n    xi.item.DAHLIA,\n    xi.item.FLAX_FLOWER,\n    xi.item.LILAC,\n    xi.item.LYCOPODIUM_FLOWER,\n    xi.item.MARGUERITE,\n    xi.item.OLIVE_FLOWER,\n    xi.item.PAPAKA_GRASS,\n    xi.item.PHALAENOPSIS,\n    xi.item.RAIN_LILY,\n    xi.item.RED_ROSE,\n    xi.item.SNOW_LILY,\n    xi.item.SWEET_WILLIAM,\n    xi.item.TAHRONGI_CACTUS,\n    xi.item.WATER_LILY,\n    xi.item.WIJNRUIT,\n}\n\nlocal function isTradeInTable(trade, itemTable)\n    for _, itemId in ipairs(itemTable) do\n        if npcUtil.tradeHasExactly(trade, itemId) then\n            return true\n        end\n    end\n\n    return false\nend\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status ~= xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.WINDURST_WALLS] =\n        {\n            ['Ojha_Rhawash'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, xi.item.LILAC) then\n                        return quest:progressEvent(10000, 0, 239, 2)\n                    elseif isTradeInTable(trade, flowerItems) then\n                        return quest:progressEvent(10000, 0, 239, 1)\n                    else\n                        return quest:progressEvent(10000, 0, 239, 0)\n                    end\n                end,\n\n                onTrigger = quest:progressEvent(10000, 0, 239, 10),\n            },\n\n            onEventFinish =\n            {\n                [10000] = function(player, csid, option, npc)\n                    -- Three possible event options are returned from the above triggers:\n                    -- 0    : Invalid Item was traded\n                    -- 1    : Valid Item was traded\n                    -- 10   : Cancel/Exit event option.\n                    -- 3002 : Lilac was traded\n\n                    -- Correct trade option (Lilac).\n                    if option == 3002 then\n                        if quest:complete(player) then\n                            player:confirmTrade()\n                            local mhflag = player:getMoghouseFlag()\n                            player:setMoghouseFlag(mhflag + 0x0004)\n                            player:messageSpecial(windurstWallsID.text.MOGHOUSE_EXIT)\n                        end\n\n                    else\n                        -- Confirm trade if there was a trade.\n                        if option == 1 then\n                            player:confirmTrade()\n                        end\n\n                        -- Start quest if it wasn't.\n                        if player:getQuestStatus(quest.areaId, quest.questId) == xi.questStatus.QUEST_AVAILABLE then\n                            quest:begin(player)\n                        end\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.WINDURST_WALLS] =\n        {\n            ['Ojha_Rhawash'] =\n            {\n                onTrade = function(player, npc, trade)\n                    -- NOTE: After completing this quest, trade is not consumed.\n\n                    if npcUtil.tradeHasExactly(trade, xi.item.LILAC) then\n                        return quest:progressEvent(10000, 0, 239, 4)\n                    elseif isTradeInTable(trade, flowerItems) then\n                        return quest:progressEvent(10000, 0, 239, 5)\n                    else\n                        return quest:progressEvent(10000, 0, 239, 0)\n                    end\n                end,\n\n                onTrigger = quest:progressEvent(10000, 0, 239, 10),\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/windurst/Food_for_Thought.lua"]={["Path"]="scripts/quests/windurst/Food_for_Thought.lua",["SHA256"]="9fd2e44b95b792f032ac91f816633c40bd617c0b51176b9a5d1ad90fc6525b37",["Text"]="-----------------------------------\n-- Food for Thought\n-----------------------------------\n-- !addquest 2 14\n-- Kenapa-Keppa   : !pos 27 -6 -199 238\n-- Kerutoto       : !pos 13 -5 -157 238\n-- Ohbiru-Dohbiru : !pos 23 -5 -193 238\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.WINDURST, xi.quest.id.windurst.FOOD_FOR_THOUGHT)\n\nquest.reward =\n{\n    fame  = 20,\n    fameArea = xi.fameArea.WINDURST,\n    title = xi.title.FAST_FOOD_DELIVERER,\n}\n\nlocal kenapaTradeEventFinish = function(player, csid, option, npc)\n    player:confirmTrade()\n    player:addGil(120)\n\n    if\n        quest:getVar(player, 'kerutotoProg') == 2 and\n        quest:getVar(player, 'ohbiruProg') == 3\n    then\n        if quest:complete(player) then\n            quest:setMustZone(player)\n        end\n    else\n        quest:setVar(player, 'kenapaProg', 4)\n    end\nend\n\nlocal ohbiruTradeEventFinish = function(player, csid, option, npc)\n    player:confirmTrade()\n    player:addGil(440)\n\n    if\n        quest:getVar(player, 'kerutotoProg') == 2 and\n        quest:getVar(player, 'kenapaProg') == 4\n    then\n        if quest:complete(player) then\n            quest:setMustZone(player)\n        end\n    else\n        quest:setVar(player, 'ohbiruProg', 3)\n    end\nend\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n            ['Kenapa-Keppa'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:getVar('Quest[2][50]Option') ~= 1 then -- Getting the dialogue about the cactus in the quest \"Say it with Flowers\" takes priority and doesn't clear until they clear the quest.\n                        return quest:progressEvent(310)\n                    end\n                end\n            },\n\n            ['Kerutoto'] =\n            {\n                onTrigger = function(player, npc)\n                    local kerutotoProgress = quest:getVar(player, 'kerutotoProg')\n                    local ohbiruProgress   = quest:getVar(player, 'ohbiruProg')\n\n                    -- Player knows the researchers are hungry and quest not refused\n                    if ohbiruProgress == 1 and kerutotoProgress ~= 256 then\n                        return quest:progressEvent(313, 0, 4371)\n\n                    -- Player knows the researchers are hungry and quest refused previously\n                    elseif ohbiruProgress == 1 and kerutotoProgress == 256 then\n                        return quest:progressEvent(314, 0, 4371)\n\n                    -- Before Quest: Asks you to check on others.\n                    else\n                        return quest:event(312)\n                    end\n                end,\n            },\n\n            ['Ohbiru-Dohbiru'] =\n            {\n                onTrigger = function(player, npc)\n                    local ohbiruProgress = quest:getVar(player, 'ohbiruProg')\n\n                    if player:getVar('Quest[2][50]Prog') ~= 1 then -- The player CANNOT have the quest \"Say it with Flowers\" Active or Ranpi will not talk to you about this quest\n                        if ohbiruProgress == 0 then\n                            return quest:progressEvent(308)\n                        elseif ohbiruProgress == 1 then\n                            return quest:progressEvent(309)\n                        end\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [308] = function(player, csid, option, npc)\n                    quest:setVar(player, 'ohbiruProg', 1)\n                end,\n\n                [313] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:begin(player)\n                        quest:setVar(player, 'kerutotoProg', 1)\n                    elseif option == 1 then\n                        quest:setVar(player, 'kerutotoProg', 256)\n                    end\n                end,\n\n                [314] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:begin(player)\n                        quest:setVar(player, 'kerutotoProg', 1)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n            ['Kenapa-Keppa'] =\n            {\n                onTrade = function(player, npc, trade)\n                    local kenapaProg = quest:getVar(player, 'kenapaProg')\n\n                    if npcUtil.tradeHasExactly(trade, xi.item.HARD_BOILED_EGG) then\n                        -- Traded item without receiving order\n                        if kenapaProg < 3 then\n                            if math.randomInt(1, 100) <= 50 then\n                                return quest:progressEvent(331)\n                            else\n                                return quest:progressEvent(330, 120)\n                            end\n\n                        -- Traded item after receiving order\n                        elseif kenapaProg == 3 then\n                            return quest:progressEvent(327, 120)\n                        end\n                    else\n                        return quest:progressEvent(329)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    local kenapaProg = quest:getVar(player, 'kenapaProg')\n\n                    if kenapaProg == 0 then\n                        return quest:progressEvent(318)\n                    elseif kenapaProg == 1 then\n                        return quest:progressEvent(319)\n                    elseif kenapaProg == 2 then\n                        return quest:progressEvent(320, 0, xi.item.HARD_BOILED_EGG)\n                    elseif kenapaProg == 3 then\n                        local randEvent = math.randomInt(1, 3)\n\n                        if randEvent == 1 then\n                            return quest:progressEvent(320, 0, xi.item.HARD_BOILED_EGG) -- Repeats Order\n                        elseif randEvent == 2 then\n                            return quest:progressEvent(321) -- 'Or Whatever'\n                        else\n                            return quest:progressEvent(328) -- '..<Grin>..'\n                        end\n                    end\n                end\n            },\n\n            ['Kerutoto'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        npcUtil.tradeHasExactly(trade, xi.item.SLICE_OF_GRILLED_HARE) and\n                        quest:getVar(player, 'kerutotoProg') == 1\n                    then\n                        return quest:progressEvent(332, 440)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    local kerutotoProgress = quest:getVar(player, 'kerutotoProg')\n\n                    if kerutotoProgress == 1 then\n                        return quest:progressEvent(315, 0, xi.item.SLICE_OF_GRILLED_HARE)\n                    elseif kerutotoProgress == 2 then\n                        return quest:progressEvent(333)\n                    end\n                end,\n            },\n\n            ['Leepe-Hoppe'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(311)\n                end,\n            },\n\n            ['Ohbiru-Dohbiru'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, { xi.item.CUP_OF_WINDURSTIAN_TEA, xi.item.TORTILLA, xi.item.CLUMP_OF_PAMTAM_KELP }) then\n                        local ohbiruProgress = quest:getVar(player, 'ohbiruProg')\n\n                        -- Traded all 3 items & Didn't ask for order\n                        if ohbiruProgress < 2 then\n                            if math.randomInt(1, 100) <= 50 then\n                                return quest:progressEvent(325, 440)\n                            else\n                                return quest:progressEvent(326)\n                            end\n\n                        -- Traded all 3 items after receiving order\n                        elseif ohbiruProgress == 2 then\n                            return quest:progressEvent(322, 440)\n                        end\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    local ohbiruProgress = quest:getVar(player, 'ohbiruProg')\n\n                    if ohbiruProgress < 2 then\n                        return quest:progressEvent(316, 0, 4493, 624, 4408)\n                    elseif ohbiruProgress == 2 then\n                        return quest:progressEvent(317, 0, 4493, 624, 4408)\n                    elseif ohbiruProgress == 3 then\n                        return quest:progressEvent(324)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [316] = function(player, csid, option, npc)\n                    quest:setVar(player, 'ohbiruProg', 2)\n                end,\n\n                [318] = function(player, csid, option, npc)\n                    quest:setVar(player, 'kenapaProg', 1)\n                end,\n\n                [319] = function(player, csid, option, npc)\n                    quest:setVar(player, 'kenapaProg', 2)\n                end,\n\n                [320] = function(player, csid, option, npc)\n                    quest:setVar(player, 'kenapaProg', 3)\n                end,\n\n                [322] = ohbiruTradeEventFinish,\n                [325] = ohbiruTradeEventFinish,\n                [326] = ohbiruTradeEventFinish,\n\n                [327] = kenapaTradeEventFinish,\n                [330] = kenapaTradeEventFinish,\n                [331] = kenapaTradeEventFinish,\n\n                [332] = function(player, csid, option, npc)\n                    player:confirmTrade()\n                    player:addGil(440)\n\n                    if\n                        quest:getVar(player, 'kenapaProg') == 4 and\n                        quest:getVar(player, 'ohbiruProg') == 3\n                    then\n                        if quest:complete(player) then\n                            quest:setMustZone(player)\n                        end\n                    else\n                        quest:setVar(player, 'kerutotoProg', 2)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED and quest:getMustZone(player)\n        end,\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n            ['Kerutoto']       = quest:event(304):replaceDefault(),\n            ['Ohbiru-Dohbiru'] = quest:event(344):replaceDefault(),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/windurst/From_Saplings_Grow.lua"]={["Path"]="scripts/quests/windurst/From_Saplings_Grow.lua",["SHA256"]="bfb61982793358276dcd27a525414f4cd8f9a54a493f73a7748aba3a70e110fd",["Text"]="-----------------------------------\n-- From Saplings Grow\n-- Perih Vashai !pos 117 -3 92 241\n-- qm1 !pos -157 -8 198.2 113\n-----------------------------------\nlocal windurstWoodsID = zones[xi.zone.WINDURST_WOODS]\nlocal capeTerigganID  = zones[xi.zone.CAPE_TERIGGAN]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.WINDURST, xi.quest.id.windurst.FROM_SAPLINGS_GROW)\n\nquest.reward =\n{\n    fame = 20,\n    fameArea = xi.fameArea.WINDURST,\n}\n\nquest.sections =\n{\n    -- Section: Quest available\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:canEquipItem(xi.item.BOW_OF_TRIALS, true) and\n                player:getCharSkillLevel(xi.skill.ARCHERY) / 10 >= 250 and\n                not player:hasKeyItem(xi.keyItem.WEAPON_TRAINING_GUIDE)\n        end,\n\n        [xi.zone.WINDURST_WOODS] =\n        {\n            ['Perih_Vashai'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(661):oncePerZone() -- start\n                end,\n            },\n\n            onEventFinish =\n            {\n                [661] = function(player, csid, option, npc)\n                    if\n                        player:hasItem(xi.item.BOW_OF_TRIALS) or\n                        npcUtil.giveItem(player, xi.item.BOW_OF_TRIALS)\n                    then\n                        npcUtil.giveKeyItem(player, xi.keyItem.WEAPON_TRAINING_GUIDE)\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest accepted\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.WINDURST_WOODS] =\n        {\n            ['Perih_Vashai'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.ANNALS_OF_TRUTH) then\n                        return quest:progressEvent(666) -- complete\n                    elseif player:hasKeyItem(xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH) then\n                        return quest:event(665) -- cont 2\n                    else\n                        return quest:event(662, 0, xi.item.BOW_OF_TRIALS, 0, 0, player:hasItem(xi.item.BOW_OF_TRIALS) and 2 or 0) -- cont 1\n                    end\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, xi.item.BOW_OF_TRIALS) then\n                        local wsPoints = trade:getItem(0):getWeaponskillPoints()\n\n                        if wsPoints < 300 then\n                            return quest:event(663) -- unfinished weapon\n                        else\n                            return quest:progressEvent(664, 0, 0, xi.keyItem.ANNALS_OF_TRUTH) -- finished weapon\n                        end\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [662] = function(player, csid, option, npc)\n                    if option == 1 and not player:hasItem(xi.item.BOW_OF_TRIALS) then\n                        npcUtil.giveItem(player, xi.item.BOW_OF_TRIALS)\n                    elseif option == 3 then\n                        player:delQuest(xi.questLog.WINDURST, xi.quest.id.windurst.FROM_SAPLINGS_GROW)\n                        player:delKeyItem(xi.keyItem.WEAPON_TRAINING_GUIDE)\n                        player:delKeyItem(xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH)\n                    end\n                end,\n\n                [664] = function(player, csid, option, npc)\n                    player:confirmTrade()\n                    npcUtil.giveKeyItem(player, xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH)\n                end,\n\n                [666] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH)\n                        player:delKeyItem(xi.keyItem.ANNALS_OF_TRUTH)\n                        player:delKeyItem(xi.keyItem.WEAPON_TRAINING_GUIDE)\n                        player:addLearnedWeaponskill(xi.wsUnlock.EMPYREAL_ARROW)\n                        player:messageSpecial(windurstWoodsID.text.EMPYREAL_ARROW_LEARNED)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.CAPE_TERIGGAN] =\n        {\n            ['qm1'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:getLocalVar('killed_wsnm') == 1 then\n                        player:setLocalVar('killed_wsnm', 0)\n                        return quest:keyItem(xi.keyItem.ANNALS_OF_TRUTH)\n                    elseif\n                        player:hasKeyItem(xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH) and\n                        not player:hasKeyItem(xi.keyItem.ANNALS_OF_TRUTH) and\n                        npcUtil.popFromQM(player, npc, capeTerigganID.mob.STOLAS, { hide = 0 })\n                    then\n                        return quest:messageSpecial(capeTerigganID.text.SENSE_OMINOUS_PRESENCE)\n                    end\n                end,\n            },\n\n            ['Stolas'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    if player:hasKeyItem(xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH) then\n                        player:setLocalVar('killed_wsnm', 1)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/windurst/Glyph_Hanger.lua"]={["Path"]="scripts/quests/windurst/Glyph_Hanger.lua",["SHA256"]="34bed3b0b210d5fb8a026c17614e8845905d73201a2fdfefe9c801caacc6c242",["Text"]="-----------------------------------\n-- Glyph Hanger\n-----------------------------------\n-- !addquest 2 30\n-- Hariga-Origa : !pos -62 -6 105 238\n-- Ipupu        : !pos 251.745 -5.5 35.539 115\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.WINDURST, xi.quest.id.windurst.GLYPH_HANGER)\n\nquest.reward =\n{\n    keyItem  = xi.keyItem.MAP_OF_THE_HORUTOTO_RUINS,\n    fameArea = xi.fameArea.WINDURST,\n    fame     = 20,\n    exp      = 2000,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n            ['Hariga-Origa'] = quest:progressEvent(381),\n\n            onEventFinish =\n            {\n                [381] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:begin(player)\n                        npcUtil.giveKeyItem(player, xi.keyItem.NOTE_FROM_HARIGA_ORIGA)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n            ['Hariga-Origa'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.NOTE_FROM_IPUPU) then\n                        return quest:progressEvent(385)\n                    else\n                        return quest:event(382)\n                    end\n                end,\n            },\n\n            ['Serukoko'] =\n            {\n                onTrigger = function(player, npc)\n                    if not player:hasKeyItem(xi.keyItem.NOTE_FROM_IPUPU) then\n                        return quest:progressEvent(383)\n                    end\n                end,\n            },\n\n            ['Sohdede'] =\n            {\n                onTrigger = function(player, npc)\n                    if not player:hasKeyItem(xi.keyItem.NOTE_FROM_IPUPU) then\n                        return quest:progressEvent(384)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [385] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.NOTE_FROM_IPUPU)\n\n                        -- Player must zone before being able to flag the next quest\n                        player:setLocalVar('Quest[2][20]mustZone', 1)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.WEST_SARUTABARUTA] =\n        {\n            ['Ipupu'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.NOTE_FROM_HARIGA_ORIGA) then\n                        return quest:progressEvent(47, 0, xi.keyItem.NOTE_FROM_HARIGA_ORIGA)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [47] = function(player, csid, option, npc)\n                    player:delKeyItem(xi.keyItem.NOTE_FROM_HARIGA_ORIGA)\n                    npcUtil.giveKeyItem(player, xi.keyItem.NOTE_FROM_IPUPU)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED and\n                not player:hasCompletedQuest(xi.questLog.WINDURST, xi.quest.id.windurst.CHASING_TALES)\n        end,\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n            ['Hariga-Origa'] = quest:event(386):replaceDefault()\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/windurst/In_a_Stew.lua"]={["Path"]="scripts/quests/windurst/In_a_Stew.lua",["SHA256"]="b18b01c4604b0f87b5052c35d3b94d5e27f1defe4445d8584534b5fe1caf32f2",["Text"]="-----------------------------------\n-- In a Stew\n-----------------------------------\n-- Log ID: 2, Quest ID: 45\n-- Kuoh Rhel   : !pos 131.437 -6 -102.723\n-- Matata      : !pos 131 -5 -109\n-- Ranpi-Monpi : !pos -116 -3 52\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.WINDURST, xi.quest.id.windurst.IN_A_STEW)\n\nquest.reward =\n{\n    fame     = 10,\n    fameArea = xi.fameArea.WINDURST,\n    gil      = 900,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return vars.Prog == 0 and\n            vars.Wait < NextConquestTally() and\n            player:hasCompletedQuest(xi.questLog.WINDURST, xi.quest.id.windurst.CHOCOBILIOUS) and\n            player:getFameLevel(xi.fameArea.WINDURST) >= 2 and\n            not xi.quest.getMustZone(player, xi.questLog.WINDURST, xi.quest.id.windurst.CHOCOBILIOUS)\n        end,\n\n        [xi.zone.WINDURST_WOODS] =\n        {\n            ['Kuoh_Rhel'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.IN_A_STEW) == xi.questStatus.QUEST_AVAILABLE then\n                        return quest:progressEvent(235)\n                    else\n                        return quest:progressEvent(234) -- Repeat after conquest tally\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [234] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:setVar(player, 'Prog', 1)\n                    end\n                end,\n\n                [235] = function(player, csid, option, npc)\n                    quest:begin(player)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return vars.Prog >= 1\n        end,\n\n        [xi.zone.WINDURST_WOODS] =\n        {\n            ['Kuoh_Rhel'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 2 then\n                        return quest:progressEvent(239)\n                    else\n                        return quest:event(236) -- Reminder\n                    end\n                end,\n            },\n\n            ['Matata'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(237) -- Gives the player a hint to talk to Ranpi-Monpi\n                end,\n            },\n\n            onEventFinish =\n            {\n                [239] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        quest:setMustZone(player)\n                        player:delKeyItem(xi.keyItem.RANPI_MONPIS_SPECIAL_STEW)\n                        quest:setVar(player, 'Wait', NextConquestTally())\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n            ['Ranpi-Monpi'] =\n            {\n                onTrigger = function(player, npc)\n                    local optional = quest:getVar(player, 'Option')\n\n                    if player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.A_CRISIS_IN_THE_MAKING) ~= xi.questStatus.QUEST_ACCEPTED then -- The player CANNOT have the quest \"A Crisis in the Making\" Active or Ranpi will not talk to you about this quest\n                        if quest:getVar(player, 'Prog') == 2 then\n                            return quest:event(557) -- Reminder to finish quest\n                        elseif\n                            optional == 1 or\n                            player:hasCompletedQuest(xi.questLog.WINDURST, xi.quest.id.windurst.CHOCOBILIOUS)\n                        then\n                            return quest:event(555, 0, xi.item.WOOZYSHROOM) -- Reminder to get Woozyshrooms\n                        elseif optional == 0 then\n                            return quest:event(554, 0, xi.item.WOOZYSHROOM) -- Requests 3x Woozyshrooms. Only plays the first time the player does the quest\n                        end\n                    end\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, { { xi.item.WOOZYSHROOM, 3 } }) then\n                        return quest:progressEvent(556)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [554] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Option', 1)\n                end,\n\n                [556] = function(player, csid, option, npc)\n                    player:confirmTrade()\n                    npcUtil.giveKeyItem(player, xi.keyItem.RANPI_MONPIS_SPECIAL_STEW)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.WINDURST_WOODS] =\n        {\n            ['Kuoh_Rhel'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getMustZone(player) then\n                        return quest:event(240)\n                    end\n                end,\n            },\n\n            ['Matata'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getMustZone(player) then\n                        return quest:event(241)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/windurst/Let_Sleeping_Dogs_Lie.lua"]={["Path"]="scripts/quests/windurst/Let_Sleeping_Dogs_Lie.lua",["SHA256"]="7fdfa5c79b5578cd8bd4a6c7951edef0b0389dc4ecc155d462cb29694013ed65",["Text"]="-----------------------------------\n-- Let Sleeping Dogs Lie\n-----------------------------------\n-- Log ID: 2, Quest ID: 46\n-- Paku-Nakku      !pos 127.189 -5.750 164.648\n-- Pechiru-Mashiru !pos 163.589 -1.249 157.589\n-- Maabu-Sonbu     !pos -107.345 -3.250 108.138\n-- qm_pepper       !pos -429.603 24.760 473.015\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.WINDURST, xi.quest.id.windurst.LET_SLEEPING_DOGS_LIE)\n\nquest.reward =\n{\n    fame     = 40,\n    fameArea = xi.fameArea.WINDURST,\n    item     = xi.item.HYPNO_STAFF,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getFameLevel(xi.fameArea.WINDURST) >= 4\n        end,\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n            ['Paku-Nakku'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(481)\n                end,\n            },\n\n            ['Akkeke']          = quest:event(484),\n            ['Chomoro-Kyotoro'] = quest:event(489),\n            ['Foi-Mui']         = quest:event(486),\n            ['Kirarara']        = quest:event(485),\n            ['Koko_Lihzeh']     = quest:event(488),\n            ['Mashuu-Ajuu']     = quest:event(483),\n            ['Rukuku']          = quest:event(487),\n\n            onEventFinish =\n            {\n                [481] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.PORT_WINDURST] =\n        {\n            ['Maabu-Sonbu'] =\n            {\n                onTrigger = function(player, npc)\n                    local option = quest:getVar(player, 'Option')\n                    local progress = quest:getVar(player, 'Prog')\n\n                    if progress == 0 then\n                        return quest:progressEvent(319, 0, xi.item.REMEDY, xi.item.BLAZING_PEPPERS, xi.item.SICKLE)\n                    elseif progress == 1 then\n                        return quest:event(320, 0, xi.item.REMEDY, xi.item.BLAZING_PEPPERS, xi.item.SICKLE)\n                    elseif progress == 2 and option == 1 then\n                        return quest:event(321, 0, xi.item.BLAZING_PEPPERS)\n                    elseif progress == 2 and option == 2 then\n                        return quest:event(321, 0, xi.item.REMEDY)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [319] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            },\n        },\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n\n            ['Akkeke'] =\n            {\n                onTrigger = function(player, npc)\n                    local progress = quest:getVar(player, 'Prog')\n\n                    if progress <= 3 then\n                        return quest:event(484)\n                    elseif progress == 4 then\n                        return quest:event(502)\n                    end\n                end,\n            },\n\n            ['Chomoro-Kyotoro'] =\n            {\n                onTrigger = function(player, npc)\n                    local progress = quest:getVar(player, 'Prog')\n\n                    if progress <= 3 then\n                        return quest:event(489)\n                    elseif progress == 4 then\n                        return quest:event(507)\n                    end\n                end,\n            },\n\n            ['Fuepepe'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') <= 3 then\n                        return quest:event(493)\n                    end\n                end,\n            },\n\n            ['Foi-Mui'] =\n            {\n                onTrigger = function(player, npc)\n                    local progress = quest:getVar(player, 'Prog')\n\n                    if progress <= 3 then\n                        return quest:event(486)\n                    elseif progress == 4 then\n                        return quest:event(504)\n                    end\n                end,\n            },\n\n            ['Kirarara'] =\n            {\n                onTrigger = function(player, npc)\n                    local progress = quest:getVar(player, 'Prog')\n\n                    if progress <= 3 then\n                        return quest:event(485)\n                    elseif progress == 4 then\n                        return quest:event(503)\n                    end\n                end,\n            },\n\n            ['Koko_Lihzeh'] =\n            {\n                onTrigger = function(player, npc)\n                    local progress = quest:getVar(player, 'Prog')\n\n                    if progress <= 3 then\n                        return quest:event(488)\n                    elseif progress == 4 then\n                        return quest:event(506)\n                    end\n                end,\n            },\n\n            ['Mashuu-Ajuu'] =\n            {\n                onTrigger = function(player, npc)\n                    local progress = quest:getVar(player, 'Prog')\n\n                    if progress <= 3 then\n                        return quest:event(483)\n                    elseif progress == 4 then\n                        return quest:event(501)\n                    end\n                end,\n            },\n\n            ['Moreno-Toeno'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') <= 3 then\n                        return quest:event(491)\n                    end\n                end,\n            },\n\n            ['Paku-Nakku'] =\n            {\n                onTrigger = function(player, npc)\n                    local progress = quest:getVar(player, 'Prog')\n\n                    if progress <= 2 then\n                        return quest:event(482)\n                    elseif progress == 3 then\n                        return quest:progressEvent(499)\n                    elseif progress == 4 then\n                        return quest:event(500)\n                    end\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if quest:getVar(player, 'Prog') == 1 then\n                        if npcUtil.tradeHas(trade, xi.item.BLAZING_PEPPERS) then\n                            quest:setVar(player, 'Option', 1) -- Traded Peppers\n                            return quest:progressEvent(494, 0, 1)\n                        elseif npcUtil.tradeHas(trade, xi.item.REMEDY) then\n                            quest:setVar(player, 'Option', 2) -- Traded a Remedy\n                            return quest:progressEvent(494)\n                        end\n                    end\n                end,\n            },\n\n            ['Pechiru-Mashiru'] =\n            {\n                onTrigger = function(player, npc)\n                    local option = quest:getVar(player, 'Option')\n                    local progress = quest:getVar(player, 'Prog')\n\n                    if progress == 0 then\n                        return quest:event(490)\n                    elseif progress == 1 then\n                        return quest:event(492)\n                    elseif progress == 2 then\n                        if option == 1 then\n                            return quest:progressEvent(495, 0, xi.item.REMEDY, xi.item.BLAZING_PEPPERS, 1) -- Player had traded Peppers to Paku-Nakku\n                        elseif option == 2 then\n                            return quest:progressEvent(495, 0, xi.item.REMEDY, xi.item.BLAZING_PEPPERS, 0) -- Player had traded a Remedy to Paku-Nakku\n                        end\n                    elseif progress == 3 then\n                        return quest:event(496)\n                    elseif progress == 4 then\n                        return quest:progressEvent(497)\n                    end\n                end,\n            },\n\n            ['Rukuku'] =\n            {\n                onTrigger = function(player, npc)\n                    local progress = quest:getVar(player, 'Prog')\n\n                    if progress <= 3 then\n                        return quest:event(487)\n                    elseif progress == 4 then\n                        return quest:event(505)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [494] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                    player:confirmTrade()\n                end,\n\n                [495] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 3)\n                end,\n\n                [497] = function(player, csid, option, npc)\n                    quest:complete(player)\n                end,\n\n                -- The title comes with the spoiled ending, not with the reward.\n                [499] = function(player, csid, option, npc)\n                    if option == 2 then\n                        player:addTitle(xi.title.SPOILSPORT)\n                        quest:setVar(player, 'Prog', 4)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/windurst/Lure_of_the_Wildcat_Windurst.lua"]={["Path"]="scripts/quests/windurst/Lure_of_the_Wildcat_Windurst.lua",["SHA256"]="c53e7511a87c7d9a30a9821f00b373184f03fa9078fb6c99509bdc46cb2fe210",["Text"]="-----------------------------------\n-- Lure of the Wildcat (Windurst)\n-----------------------------------\n-- !addquest 2 94\n-- Ibwam : !pos -25.655 1.749 -60.651 241\n-----------------------------------\nlocal windurstWoodsID = zones[xi.zone.WINDURST_WOODS]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.WINDURST, xi.quest.id.windurst.LURE_OF_THE_WILDCAT)\n\nquest.reward =\n{\n    fame     = 0,\n    fameArea = xi.fameArea.WINDURST,\n    keyItem  = xi.keyItem.GREEN_INVITATION_CARD,\n}\n\nlocal wildcatNpcData =\n{\n    ['Soni-Muni'        ] = {  0, 735 }, -- !pos -17.073 1.749 -59.327 241\n    ['Etsa_Rhuyuli'     ] = {  1, 734 }, -- !pos 62.482 -8.499 -139.836 241\n    ['Cayu_Pensharhumi' ] = {  2, 733 }, -- !pos 39.437 -0.91 -40.808 241\n    ['Umumu'            ] = {  3, 731 }, -- !pos 32.575 -5.25 141.372 241\n    ['Nanaa_Mihgo'      ] = {  4, 732 }, -- !pos 62 -4 240 241\n    ['Yoriri'           ] = {  5, 496 }, -- !pos 65.268 -8.5 -58.309 239\n    ['Shantotto'        ] = {  6, 498 }, -- !pos 122 -2 112 239\n    ['Moan-Maon'        ] = {  7, 497 }, -- !pos 88.244 -6.32 148.912 239\n    ['Chomomo'          ] = {  8, 499 }, -- !pos -1.262 -11 290.224 239\n    ['Naih_Arihmepp'    ] = {  9, 500 }, -- !pos -64.578 -13.465 202.147 239\n    ['Npopo'            ] = { 10, 936 }, -- !pos -35.464 -5.999 239.12 238\n    ['Lago-Charago'     ] = { 11, 940 }, -- !pos -57.271 -11.75 92.503 238\n    ['Amagusa-Chigurusa'] = { 12, 937 }, -- !pos -28.746 -4.5 61.954 238\n    ['Funpo-Shipo'      ] = { 13, 938 }, -- !pos -44.091 -4.499 41.728 238\n    ['Kyume-Romeh'      ] = { 14, 939 }, -- !pos -58 -4 23 238\n    ['Kunchichi'        ] = { 15, 623 }, -- !pos -115.933 -4.25 109.533 240\n    ['Yaman-Hachuman'   ] = { 16, 624 }, -- !pos -101.209 -4.25 110.886 240\n    ['Choyi_Totlihpa'   ] = { 17, 622 }, -- !pos -58.927 -5.732 132.819 240\n    ['Three_of_Clubs'   ] = { 18, 625 }, -- !pos -7.238 -5 106.982 240\n    ['Yujuju'           ] = { 19, 621 }, -- !pos 201.523 -4.785 138.978 240\n}\n\nlocal wildcatOnTrigger = function(player, npc)\n    local npcData = wildcatNpcData[npc:getName()]\n\n    if not quest:isVarBitsSet(player, 'Prog', npcData[1]) then\n        return quest:progressEvent(npcData[2])\n    end\nend\n\nlocal wildcatOnEventFinish = function(player, csid, option, npc)\n    quest:setVarBit(player, 'Prog', wildcatNpcData[npc:getName()][1])\nend\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                xi.settings.main.ENABLE_TOAU == 1\n        end,\n\n        [xi.zone.WINDURST_WOODS] =\n        {\n            ['Ibwam'] = quest:progressEvent(736),\n\n            onEventFinish =\n            {\n                [736] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.GREEN_SENTINEL_BADGE)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.PORT_WINDURST] =\n        {\n            ['Choyi_Totlihpa'] = wildcatOnTrigger,\n            ['Kunchichi'     ] = wildcatOnTrigger,\n            ['Three_of_Clubs'] = wildcatOnTrigger,\n            ['Yaman-Hachuman'] = wildcatOnTrigger,\n            ['Yujuju'        ] = wildcatOnTrigger,\n\n            onEventFinish =\n            {\n                [621] = wildcatOnEventFinish,\n                [622] = wildcatOnEventFinish,\n                [623] = wildcatOnEventFinish,\n                [624] = wildcatOnEventFinish,\n                [625] = wildcatOnEventFinish,\n            },\n        },\n\n        [xi.zone.WINDURST_WALLS] =\n        {\n            ['Chomomo'      ] = wildcatOnTrigger,\n            ['Moan-Maon'    ] = wildcatOnTrigger,\n            ['Naih_Arihmepp'] = wildcatOnTrigger,\n            ['Shantotto'    ] = wildcatOnTrigger,\n            ['Yoriri'       ] = wildcatOnTrigger,\n\n            onEventFinish =\n            {\n                [496] = wildcatOnEventFinish,\n                [497] = wildcatOnEventFinish,\n                [498] = wildcatOnEventFinish,\n                [499] = wildcatOnEventFinish,\n                [500] = wildcatOnEventFinish,\n            },\n        },\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n            ['Amagusa-Chigurusa'] = wildcatOnTrigger,\n            ['Funpo-Shipo'      ] = wildcatOnTrigger,\n            ['Kyume-Romeh'      ] = wildcatOnTrigger,\n            ['Lago-Charago'     ] = wildcatOnTrigger,\n            ['Npopo'            ] = wildcatOnTrigger,\n\n            onEventFinish =\n            {\n                [936] = wildcatOnEventFinish,\n                [937] = wildcatOnEventFinish,\n                [938] = wildcatOnEventFinish,\n                [939] = wildcatOnEventFinish,\n                [940] = wildcatOnEventFinish,\n            },\n        },\n\n        [xi.zone.WINDURST_WOODS] =\n        {\n            ['Ibwam'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 0 then\n                        return quest:event(737)\n                    elseif utils.mask.isFull(questProgress, 20) then\n                        return quest:progressEvent(739)\n                    else\n                        return quest:event(738)\n                    end\n                end,\n            },\n\n            ['Cayu_Pensharhumi'] = wildcatOnTrigger,\n            ['Etsa_Rhuyuli'    ] = wildcatOnTrigger,\n            ['Nanaa_Mihgo'     ] = wildcatOnTrigger,\n            ['Soni-Muni'       ] = wildcatOnTrigger,\n            ['Umumu'           ] = wildcatOnTrigger,\n\n            onEventFinish =\n            {\n                [731] = wildcatOnEventFinish,\n                [732] = wildcatOnEventFinish,\n                [733] = wildcatOnEventFinish,\n                [734] = wildcatOnEventFinish,\n                [735] = wildcatOnEventFinish,\n\n                [739] = function(player, csid, option, npc)\n                    player:delKeyItem(xi.keyItem.GREEN_SENTINEL_BADGE)\n                    player:messageSpecial(windurstWoodsID.text.KEYITEM_LOST, xi.keyItem.GREEN_SENTINEL_BADGE)\n\n                    quest:complete(player)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/windurst/Making_Amends.lua"]={["Path"]="scripts/quests/windurst/Making_Amends.lua",["SHA256"]="28c49afb71f3b7cc25a7863bd50a65a7d12cd3df895662c8f10b5acea3146857",["Text"]="-----------------------------------\n-- Making Amends\n-----------------------------------\n-- Log ID: 2, Quest ID: 3\n-- Hakkuru-Rinkuru !pos -111 -4 101 240\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.WINDURST, xi.quest.id.windurst.MAKING_AMENDS)\n\nquest.reward =\n{\n    fameArea = xi.fameArea.WINDURST,\n    fame     = 30,\n    title    = xi.title.QUICK_FIXER,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getFameLevel(xi.fameArea.WINDURST) >= 2\n        end,\n\n        [xi.zone.PORT_WINDURST] =\n        {\n            ['Hakkuru-Rinkuru'] = quest:progressEvent(274, 0, xi.item.BLOCK_OF_ANIMAL_GLUE),\n\n            onEventFinish =\n            {\n                [274] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.PORT_WINDURST] =\n        {\n            ['Hakkuru-Rinkuru'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(275, 0, xi.item.BLOCK_OF_ANIMAL_GLUE)\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHas(trade, { { xi.item.BLOCK_OF_ANIMAL_GLUE, 1 } }) then\n                        return quest:progressEvent(277, 1500) -- \"Obtained X gil.\" Text is baked into the CS, so gil needs to be given outside of the quest\n                    end\n                end,\n            },\n\n            ['Kuroido-Moido'] = quest:event(276),\n\n            onEventFinish =\n            {\n                [277] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:confirmTrade()\n                        player:addGil(1500)\n                        quest:setMustZone(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.PORT_WINDURST] =\n        {\n            ['Hakkuru-Rinkuru'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getMustZone(player) then\n                        return quest:event(278)\n                    else\n                        return quest:event(281):replaceDefault()\n                    end\n                end,\n            },\n\n            ['Kuroido-Moido'] =\n                        {\n                onTrigger = function(player, npc)\n                    if quest:getMustZone(player) then\n                        return quest:event(279)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/windurst/Making_the_Grade.lua"]={["Path"]="scripts/quests/windurst/Making_the_Grade.lua",["SHA256"]="444994574b2d856df46eeb071e47023d9434eb444c8efd58e4c8746082d4f359",["Text"]="-----------------------------------\n-- Making the Grade\n-----------------------------------\n-- Log ID: 2, Quest ID: 4\n-- Fuepepe         : !pos 161 -2 161 238\n-- Koru-Moru       : !pos -120 -6 124 239\n-- Chomoro-Kyotoro : !pos 133 -5 167 238\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.WINDURST, xi.quest.id.windurst.MAKING_THE_GRADE)\n\nquest.reward =\n{\n    fame     = 30,\n    fameArea = xi.fameArea.WINDURST,\n    item     = xi.item.SCROLL_OF_ASPIR,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.WINDURST, xi.quest.id.windurst.TEACHERS_PET) and\n                player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.LET_SLEEPING_DOGS_LIE) ~= xi.questStatus.QUEST_ACCEPTED and\n                player:getFameLevel(xi.fameArea.WINDURST) >= 3 and\n                player:getMainLvl() >= 10 -- Level requirement added in the March 8, 2007 update: https://www.playonline.com/pcd/update/ff11us/20070308c2bbd1/detail.html\n        end,\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n            ['Fuepepe'] = quest:progressEvent(442),\n\n            onEventFinish =\n            {\n                [442] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n            ['Chomoro-Kyotoro'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 0 then\n                        return quest:event(454)\n                    elseif questProgress == 1 then\n                        return quest:event(457)\n                    elseif questProgress == 2 then\n                        return quest:progressEvent(460)\n                    else\n                        return quest:event(461)\n                    end\n                end,\n            },\n\n            ['Fuepepe'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        npcUtil.tradeHasExactly(trade, xi.item.PILE_OF_ANSWER_SHEETS) and\n                        quest:getVar(player, 'Prog') == 0\n                    then\n                        return quest:progressEvent(455)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 0 then\n                        return quest:event(443)\n                    elseif questProgress == 1 then\n                        return quest:event(456)\n                    elseif questProgress >= 2 then\n                        return quest:event(458)\n                    end\n                end,\n            },\n\n            ['Akkeke']          = quest:event(453),\n            ['Foi-Mui']         = quest:event(449),\n            ['Kirarara']        = quest:event(447),\n            ['Koko_Lihzeh']     = quest:event(451),\n            ['Mashuu-Ajuu']     = quest:event(448),\n            ['Moreno-Toeno']    = quest:event(444),\n            ['Paku-Nakku']      = quest:event(452),\n            ['Pechiru-Mashiru'] = quest:event(445),\n            ['Rukuku']          = quest:event(450),\n            ['Tauwawa']         = quest:event(446),\n\n            onEventFinish =\n            {\n                [455] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n\n                [458] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        quest:setMustZone(player)\n                    end\n                end,\n\n                [460] = function(player, csid, option, npc)\n                    player:delKeyItem(xi.keyItem.TATTERED_TEST_SHEET)\n                    quest:setVar(player, 'Prog', 3)\n                end,\n            },\n        },\n\n        [xi.zone.WINDURST_WALLS] =\n        {\n            ['Koru-Moru'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, xi.item.PILE_OF_ANSWER_SHEETS) then\n                        if quest:getVar(player, 'Prog') == 1 then\n                            return quest:progressEvent(285)\n                        else\n                            return quest:event(287)\n                        end\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if\n                        questProgress == 0 and\n                        player:hasItem(xi.item.PILE_OF_ANSWER_SHEETS)\n                    then\n                        return quest:event(287)\n                    elseif questProgress >= 2 then\n                        return quest:event(286)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [285] = function(player, csid, option, npc)\n                    player:confirmTrade()\n\n                    npcUtil.giveKeyItem(player, xi.keyItem.TATTERED_TEST_SHEET)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED and\n                not quest:getMustZone(player)\n        end,\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n            ['Fuepepe'] = quest:event(459):importantEvent(),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/windurst/Mihgos_Amigo.lua"]={["Path"]="scripts/quests/windurst/Mihgos_Amigo.lua",["SHA256"]="791a1cb0b84b7eaa54227778f4e4cc487340aed344d2bb717da1bfa3e9f97ee4",["Text"]="-----------------------------------\n-- Mihgo's Amigo\n-----------------------------------\n-- Log ID: 2, Quest ID: 4\n-- Nanaa Mihgo !pos 62 -4 240 241\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.WINDURST, xi.quest.id.windurst.MIHGOS_AMIGO)\n\nquest.reward =\n{\n    title = xi.title.CAT_BURGLAR_GROUPIE,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.THE_TENSHODO_SHOWDOWN) ~= xi.questStatus.QUEST_ACCEPTED and -- Quest cannot be flagged if you have The Tenshodo Showdown in progress\n                player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.AS_THICK_AS_THIEVES) ~= xi.questStatus.QUEST_ACCEPTED -- Quest cannot be flagged if you have As Thick as Thieves in progress\n        end,\n\n        [xi.zone.WINDURST_WOODS] =\n        {\n            ['Nanaa_Mihgo'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.CRYING_OVER_ONIONS) == xi.questStatus.QUEST_ACCEPTED then\n                        return quest:progressEvent(81) -- Start Quest \"Mihgo's Amigo\" with quest \"Crying Over Onions\" Activated\n                    else\n                        return quest:progressEvent(80)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [80] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n\n                [81] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.WINDURST_WOODS] =\n        {\n            ['Nanaa_Mihgo'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(82)\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHas(trade, { { xi.item.YAGUDO_BEAD_NECKLACE, 4 } }) then\n                        return quest:progressEvent(88, 200)\n                    end\n                end,\n            },\n\n            ['Bopa_Greso'] = quest:event(84),\n\n            ['Cha_Lebagta'] = quest:event(85, 0, xi.item.YAGUDO_BEAD_NECKLACE),\n\n            onEventFinish =\n            {\n                [88] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:confirmTrade()\n                        player:addFame(xi.fameArea.NORG, 30)\n                        player:addGil(200) -- \"Obtained X gil.\" Text is baked into the CS, so gil needs to be given outside of the quest rewards.\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.WINDURST_WOODS] =\n        {\n            ['Nanaa_Mihgo'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getMustZone(player) then\n                        return quest:event(89)\n                    end\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHas(trade, { { xi.item.YAGUDO_BEAD_NECKLACE, 4 } }) then\n                        return quest:progressEvent(494, 200)\n                    end\n                end,\n            },\n\n            ['Cha_Lebagta'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getMustZone(player) then\n                        return quest:event(91, 0, xi.item.YAGUDO_BEAD_NECKLACE)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [494] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:confirmTrade()\n                        quest:setMustZone(player)\n                        player:addFame(xi.fameArea.NORG, 15)\n                        player:addGil(200) -- \"Obtained X gil.\" Text is baked into the CS, so gil needs to be given outside of the quest rewards.\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/windurst/One_Good_Deed.lua"]={["Path"]="scripts/quests/windurst/One_Good_Deed.lua",["SHA256"]="b96e3fe029a04fd0753e63b1e0649c26a2d186ecfb44aab5dd86d8362203114d",["Text"]="-----------------------------------\n-- One Good Deed?\n-----------------------------------\n-- Log ID: 2, Quest ID: 92\n-- Chipmy-Popmy !pos -181.466 -2.834 73.57\n-- qm_deed      !pos -321.364 -2.591 -738.066\n-----------------------------------\nlocal bayID = zones[xi.zone.BIBIKI_BAY]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.WINDURST, xi.quest.id.windurst.ONE_GOOD_DEED)\n\nquest.reward =\n{\n    fame     = 50,\n    fameArea = xi.fameArea.WINDURST,\n    exp      = 2000,\n    gil      = 3200,\n    keyItem  = xi.keyItem.MAP_OF_THE_ATTOHWA_CHASM,\n    title    = xi.title.DEED_VERIFIER,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getFameLevel(xi.fameArea.WINDURST) >= 5\n        end,\n\n        [xi.zone.PORT_WINDURST] =\n        {\n            ['Chipmy-Popmy'] = quest:progressEvent(594),\n\n            onEventFinish =\n            {\n                [594] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.PORT_WINDURST] =\n        {\n            ['Chipmy-Popmy'] =\n            {\n                onTrigger = function(player, npc)\n                    local progress = quest:getVar(player, 'Prog')\n\n                    if progress == 0 then\n                        return quest:event(596)\n                    elseif progress == 1 then\n                        return quest:progressEvent(595, 0, xi.keyItem.DEED_TO_PURGONORGO_ISLE)\n                    elseif progress == 3 then\n                        return quest:progressEvent(597)\n                    else\n                        return quest:event(599)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n\n                [595] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n\n                [597] = function(player, csid, option, npc)\n                    quest:complete(player)\n                end,\n            },\n        },\n\n        [xi.zone.BIBIKI_BAY] =\n        {\n            ['qm_deed'] =\n            {\n                onTrigger = function(player, npc)\n                    local progress = quest:getVar(player, 'Prog')\n                    local nmKilled = player:getLocalVar('NMKilled')\n\n                    if\n                        progress == 0 and\n                        nmKilled == 0 and\n                        not GetMobByID(bayID.mob.PEERIFOOL):isSpawned() and\n                        not GetMobByID(bayID.mob.PEERIFOOL + 1):isSpawned() and\n                        not GetMobByID(bayID.mob.PEERIFOOL + 2):isSpawned() and\n                        not GetMobByID(bayID.mob.PEERIFOOL + 3):isSpawned() and\n                        not GetMobByID(bayID.mob.PEERIFOOL + 4):isSpawned() and\n                        not GetMobByID(bayID.mob.PEERIFOOL + 5):isSpawned()\n                    then\n                        for i = 0, 5 do\n                            SpawnMob(bayID.mob.PEERIFOOL + i):updateClaim(player)\n                        end\n\n                        player:messageSpecial(bayID.text.IT_WAS_A_TRAP)\n                        return quest:messageSpecial(bayID.text.YOU_ARE_NOT_ALONE)\n                    elseif\n                        progress == 0 and\n                        nmKilled == 6\n                    then\n                        return quest:progressCutscene(34)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n\n                [34] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                    npcUtil.giveKeyItem(player, xi.keyItem.DEED_TO_PURGONORGO_ISLE)\n                end,\n            },\n\n            ['Peerifool'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    local nmKilled = player:getLocalVar('NMKilled')\n\n                    if quest:getVar(player, 'Prog') == 0 then\n                        player:setLocalVar('NMKilled', nmKilled + 1) -- Resets upon zoning causing the player to need to refight the NMs\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.BONEYARD_GULLY] =\n        {\n            afterZoneIn = function(player)\n                if quest:getVar(player, 'Prog') == 2 then\n                    return quest:progressEvent(8, 4, xi.keyItem.DEED_TO_PURGONORGO_ISLE, 0, 274, 8)\n                end\n            end,\n\n            onEventUpdate =\n            {\n                [8] = function(player, csid, option, npc)\n                    if option == 101 then\n                        player:updateEvent(3, xi.keyItem.MAP_OF_THE_ATTOHWA_CHASM, 0, 274, 8)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [8] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 3)\n                    npcUtil.giveKeyItem(player, xi.keyItem.MAP_OF_THE_ATTOHWA_CHASM)\n                end,\n            },\n        },\n    },\n\n    {\n    check = function(player, status, vars)\n        return status == xi.questStatus.QUEST_COMPLETED\n    end,\n\n    [xi.zone.PORT_WINDURST] =\n        {\n            ['Chipmy-Popmy'] = quest:event(598),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/windurst/Orastery_Woes.lua"]={["Path"]="scripts/quests/windurst/Orastery_Woes.lua",["SHA256"]="1de6bd778b8604e9b61241499709fd96ed12714f6e969b5d42de9aec5eaae3b3",["Text"]="-----------------------------------\n-- Orastery Woes\n-- Kuroido-Moido !pos -112.5 -4.2 102.9 240\n-- qm1 !pos 197 -8 -27.5 122\n-----------------------------------\nlocal portWindurstID = zones[xi.zone.PORT_WINDURST]\nlocal roMaeveID = zones[xi.zone.ROMAEVE]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.WINDURST, xi.quest.id.windurst.ORASTERY_WOES)\n\nquest.reward =\n{\n    fame = 20,\n    fameArea = xi.fameArea.WINDURST,\n}\n\nquest.sections =\n{\n    -- Section: Quest available\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:canEquipItem(xi.item.CLUB_OF_TRIALS, true) and\n                player:getCharSkillLevel(xi.skill.CLUB) / 10 >= 230 and\n                not player:hasKeyItem(xi.keyItem.WEAPON_TRAINING_GUIDE)\n        end,\n\n        [xi.zone.PORT_WINDURST] =\n        {\n            ['Kuroido-Moido'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(578):oncePerZone() -- start\n                end,\n            },\n\n            onEventFinish =\n            {\n                [578] = function(player, csid, option, npc)\n                    if\n                        player:hasItem(xi.item.CLUB_OF_TRIALS) or\n                        npcUtil.giveItem(player, xi.item.CLUB_OF_TRIALS)\n                    then\n                        npcUtil.giveKeyItem(player, xi.keyItem.WEAPON_TRAINING_GUIDE)\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest accepted\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.PORT_WINDURST] =\n        {\n            ['Kuroido-Moido'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.ANNALS_OF_TRUTH) then\n                        return quest:progressEvent(583) -- complete\n                    elseif player:hasKeyItem(xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH) then\n                        return quest:event(582) -- cont 2\n                    else\n                        return quest:event(579, 0, xi.item.CLUB_OF_TRIALS, 0, 0, player:hasItem(xi.item.CLUB_OF_TRIALS) and 2 or 0) -- cont 1\n                    end\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, xi.item.CLUB_OF_TRIALS) then\n                        local wsPoints = trade:getItem(0):getWeaponskillPoints()\n\n                        if wsPoints < 300 then\n                            return quest:event(580) -- unfinished weapon\n                        else\n                            return quest:progressEvent(581, 0, 0, xi.keyItem.ANNALS_OF_TRUTH) -- finished weapon\n                        end\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [579] = function(player, csid, option, npc)\n                    if option == 1 and not player:hasItem(xi.item.CLUB_OF_TRIALS) then\n                        npcUtil.giveItem(player, xi.item.CLUB_OF_TRIALS)\n                    elseif option == 3 then\n                        player:delQuest(xi.questLog.WINDURST, xi.quest.id.windurst.ORASTERY_WOES)\n                        player:delKeyItem(xi.keyItem.WEAPON_TRAINING_GUIDE)\n                        player:delKeyItem(xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH)\n                    end\n                end,\n\n                [581] = function(player, csid, option, npc)\n                    player:confirmTrade()\n                    npcUtil.giveKeyItem(player, xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH)\n                end,\n\n                [583] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH)\n                        player:delKeyItem(xi.keyItem.ANNALS_OF_TRUTH)\n                        player:delKeyItem(xi.keyItem.WEAPON_TRAINING_GUIDE)\n                        player:addLearnedWeaponskill(xi.wsUnlock.BLACK_HALO)\n                        player:messageSpecial(portWindurstID.text.BLACK_HALO_LEARNED)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.ROMAEVE] =\n        {\n            ['qm1'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:getLocalVar('killed_wsnm') == 1 then\n                        player:setLocalVar('killed_wsnm', 0)\n                        return quest:keyItem(xi.keyItem.ANNALS_OF_TRUTH)\n                    elseif\n                        player:hasKeyItem(xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH) and\n                        not player:hasKeyItem(xi.keyItem.ANNALS_OF_TRUTH) and\n                        npcUtil.popFromQM(player, npc, roMaeveID.mob.ELDHRIMNIR, { hide = 0 })\n                    then\n                        return quest:messageSpecial(roMaeveID.text.SENSE_OMINOUS_PRESENCE)\n                    end\n                end,\n            },\n\n            ['Eldhrimnir'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    if player:hasKeyItem(xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH) then\n                        player:setLocalVar('killed_wsnm', 1)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/windurst/Overnight_Delivery.lua"]={["Path"]="scripts/quests/windurst/Overnight_Delivery.lua",["SHA256"]="6887c4586dbc2c17585e017384ff1cbd146de6e1e89b814fd5e62f560a044dac",["Text"]="-----------------------------------\n-- Overnight Delivery\n-----------------------------------\n-- !addquest 2 15\n-- Kenapa-Keppa  : !pos 27 -6 -199 238\n-- Kotan-Purutan : !pos 40.32 -9 44.24 249\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.WINDURST, xi.quest.id.windurst.OVERNIGHT_DELIVERY)\n\nquest.reward =\n{\n    fame = 20,\n    fameArea = xi.fameArea.WINDURST,\n    item = xi.item.POWER_GI,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.WINDURST, xi.quest.id.windurst.FOOD_FOR_THOUGHT) and\n                player:getFameLevel(xi.fameArea.WINDURST) >= 2 and\n                not xi.quest.getMustZone(player, xi.questLog.WINDURST, xi.quest.id.windurst.FOOD_FOR_THOUGHT)\n        end,\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n            ['Kenapa-Keppa'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n                    local vanadielHour = VanadielHour()\n\n                    -- Player has previously failed this quest\n                    if questProgress == 256 then\n                        return quest:progressEvent(347)\n\n                    -- Quest Available Pattern (First attempt and previously failed)\n                    elseif vanadielHour >= 7 and vanadielHour < 24 then\n                        if questProgress == 0 then\n                            return quest:progressEvent(336)\n                        elseif questProgress == 1 then\n                            return quest:progressEvent(337)\n                        elseif questProgress == 2 then\n                            return quest:progressEvent(338)\n                        elseif questProgress == 3 then\n                            return quest:progressEvent(339)\n                        end\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [336] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n\n                [337] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n\n                [338] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 3)\n                end,\n\n                [339] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:begin(player)\n                        quest:setVar(player, 'Prog', 4)\n                    else\n                        quest:setVar(player, 'Prog', 0)\n                    end\n                end,\n\n                [347] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 0)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.MHAURA] =\n        {\n            ['Kotan-Purutan'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if\n                        not player:hasKeyItem(xi.keyItem.SMALL_BAG) and\n                        questProgress >= 4 and\n                        questProgress <= 7\n                    then\n                        local vanadielHour  = VanadielHour()\n\n                        if vanadielHour < 6 or vanadielHour >= 18 then\n                            return quest:progressEvent(141)\n                        else\n                            return quest:event(144)\n                        end\n                    else\n                        return quest:event(142)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [141] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.SMALL_BAG)\n\n                    -- Track timing by day in which the KI is due to be delivered in order\n                    -- to simplify the logic for completing this quest.\n                    if VanadielHour() < 6 then\n                        quest:setVar(player, 'dueDate', VanadielUniqueDay())\n                    else\n                        quest:setVar(player, 'dueDate', VanadielUniqueDay() + 1)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n            ['Kenapa-Keppa'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.SMALL_BAG) then\n                        local dueDate = quest:getVar(player, 'dueDate')\n                        local currentDay = VanadielUniqueDay()\n\n                        if\n                            dueDate > currentDay or\n                            (dueDate == currentDay and VanadielHour() < 6)\n                        then\n                            return quest:progressEvent(348)\n                        else\n                            return quest:progressEvent(346)\n                        end\n                    else\n                        local questProgress = quest:getVar(player, 'Prog')\n\n                        if questProgress == 4 then\n                            return quest:progressEvent(340)\n                        elseif questProgress == 5 then\n                            return quest:progressEvent(341)\n                        elseif questProgress == 6 then\n                            return quest:progressEvent(342)\n                        elseif questProgress == 7 then\n                            return quest:progressEvent(343)\n                        end\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                -- Kenapa-Keppa's reminder text cycles.  Events 340~343 loop\n                -- through the available messages.\n                [340] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 5)\n                end,\n\n                [341] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 6)\n                end,\n\n                [342] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 7)\n                end,\n\n                [343] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 4)\n                end,\n\n                [346] = function(player, csid, option, npc)\n                    player:delQuest(quest.areaId, quest.questId)\n                    player:delKeyItem(xi.keyItem.SMALL_BAG)\n                    quest:setVar(player, 'dueDate', 0)\n                    quest:setVar(player, 'Prog', 256)\n                end,\n\n                [348] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.SMALL_BAG)\n                        quest:setMustZone(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.MHAURA] =\n        {\n            ['Kotan-Purutan'] = quest:event(143):replaceDefault(),\n        },\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n            ['Ohbiru-Dohbiru'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:getFameLevel(xi.fameArea.WINDURST) < 6 then\n                        return quest:event(351):replaceDefault()\n                    end\n                end,\n            },\n\n            ['Kenapa-Keppa'] =\n            {\n                onTrigger = function(player, npc)\n                    if math.randomInt(1, 100) <= 50 then\n                        return quest:event(349):replaceDefault()\n                    else\n                        return quest:event(350):replaceDefault()\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/windurst/RNG_AF1_Sin_Hunting.lua"]={["Path"]="scripts/quests/windurst/RNG_AF1_Sin_Hunting.lua",["SHA256"]="e715975ca415287ef5c333dcc1ef0f13662a667ca31634b19ffd69df15201f86",["Text"]="-----------------------------------\n-- Sin Hunting\n-----------------------------------\n-- Log ID: 2, Quest ID: 72\n-- !addquest 2 72\n-- Perih Vashai : !pos 117 -3 92 241\n-- Perchond     : !pos -182.844 4 -164.948 166\n-- Alexius      : !pos 105 1 382 104\n-- qm2 (???)    : !pos -10.946 -1 313.810 104\n-----------------------------------\n-- The pinch of glittersand drops from the Evil Weapons around the Waters of Oblivion.\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.WINDURST, xi.quest.id.windurst.SIN_HUNTING)\n\nquest.reward =\n{\n    fame     = 20,\n    fameArea = xi.fameArea.WINDURST,\n    item     = xi.item.SNIPING_BOW,\n}\n\nquest.sections =\n{\n    -- Section: Quest is available.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getMainJob() == xi.job.RNG and\n                player:getMainLvl() >= xi.settings.main.AF1_QUEST_LEVEL\n        end,\n\n        [xi.zone.WINDURST_WOODS] =\n        {\n            ['Perih_Vashai'] = quest:progressEvent(523),\n\n            onEventFinish =\n            {\n                [523] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:begin(player)\n                        npcUtil.giveKeyItem(player, xi.keyItem.CHIEFTAINNESSS_TWINSTONE_EARRING)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest accepted.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.WINDURST_WOODS] =\n        {\n            ['Perih_Vashai'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 4 then\n                        return quest:progressEvent(527)\n                    else\n                        return quest:event(524)\n                    end\n                end,\n            },\n\n            ['Kapeh_Myohrye'] = quest:event(526),\n            ['Muhk_Johldy']   = quest:event(525),\n\n            onEventFinish =\n            {\n                [527] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.CHIEFTAINNESSS_TWINSTONE_EARRING)\n                        player:delKeyItem(xi.keyItem.PERCHONDS_ENVELOPE)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.RANGUEMONT_PASS] =\n        {\n            ['Perchond'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        quest:getVar(player, 'Prog') == 1 and\n                        npcUtil.tradeMatches(trade, { { xi.item.PINCH_OF_GLITTERSAND, 1 } })\n                    then\n                        return quest:progressEvent(5)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    local prog = quest:getVar(player, 'Prog')\n\n                    if prog == 0 then\n                        return quest:progressEvent(3, 0, xi.item.PINCH_OF_GLITTERSAND)\n                    elseif prog == 1 then\n                        return quest:event(4, 0, xi.item.PINCH_OF_GLITTERSAND)\n                    elseif prog == 2 or prog == 3 then\n                        return quest:event(6) -- Reminder to deliver the envelope.\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [3] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:setVar(player, 'Prog', 1)\n                    end\n                end,\n\n                [5] = function(player, csid, option, npc)\n                    if option == 0 then\n                        player:tradeComplete()\n                        npcUtil.giveKeyItem(player, xi.keyItem.PERCHONDS_ENVELOPE)\n                        quest:setVar(player, 'Prog', 2)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.JUGNER_FOREST] =\n        {\n            ['Alexius'] =\n            {\n                onTrigger = function(player, npc)\n                    local prog = quest:getVar(player, 'Prog')\n\n                    if prog == 2 then\n                        return quest:progressEvent(10)\n                    elseif prog == 3 then\n                        return quest:event(11)\n                    end\n                end,\n            },\n\n            ['qm2'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 3 then\n                        return quest:progressEvent(13, 0, xi.item.PINCH_OF_GLITTERSAND)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [10] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:setVar(player, 'Prog', 3)\n                    end\n                end,\n\n                [13] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:setVar(player, 'Prog', 4)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest completed.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.WINDURST_WOODS] =\n        {\n            ['Kapeh_Myohrye'] = quest:event(530):replaceDefault(),\n            ['Muhk_Johldy']   = quest:event(529):replaceDefault(),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/windurst/Rock_Racketeer.lua"]={["Path"]="scripts/quests/windurst/Rock_Racketeer.lua",["SHA256"]="d0cea408aba19e85e6937a17023bf88ce014b15936049028ff2a96412428e38a",["Text"]="-----------------------------------\n-- Rock Racketeer\n-----------------------------------\n-- Log ID: 2, Quest ID: 26\n-- Nanaa Mihgo  !pos 62 -4 240 241\n-- Ardea        !pos -198.231 -6 -71.379\n-- Varun        !pos 9.989 -2.5 -7.597\n-- Mythril Seam !pos 210 -32 -63 143\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.WINDURST, xi.quest.id.windurst.ROCK_RACKETEER)\n\nquest.reward =\n{\n    fame  = 30,\n    fameArea = xi.fameArea.WINDURST,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.WINDURST, xi.quest.id.windurst.MIHGOS_AMIGO) and\n                player:getFameLevel(xi.fameArea.WINDURST) >= 3 and\n                not xi.quest.getMustZone(player, xi.questLog.WINDURST, xi.quest.id.windurst.MIHGOS_AMIGO)\n        end,\n\n        [xi.zone.WINDURST_WOODS] =\n        {\n            ['Nanaa_Mihgo'] = quest:progressEvent(93),\n\n            onEventFinish =\n            {\n                [93] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:begin(player)\n                        npcUtil.giveKeyItem(player, xi.keyItem.SHARP_GRAY_STONE)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.WINDURST_WOODS] =\n        {\n            ['Bopa_Greso'] =\n            {\n                onTrigger = function(player, npc)\n                    -- Once the player gets the Sharp Stone, NPC goes back to default action until after the quest is complete\n                    if quest:getVar(player, 'Prog') <= 2 then\n                        return quest:event(96)\n                    end\n                end,\n            },\n\n            ['Cha_Lebagta'] =\n            {\n                onTrigger = function(player, npc)\n                    -- Once the player gets the Sharp Stone, NPC goes back to default action until after the quest is complete\n                    if quest:getVar(player, 'Prog') <= 2 then\n                        return quest:event(97)\n                    end\n                end,\n            },\n\n            ['Nanaa_Mihgo'] =\n            {\n                onTrigger = function(player, npc)\n                    local progress = quest:getVar(player, 'Prog')\n\n                    if progress == 0 then\n                        if quest:getVar(player, 'Option') == 0 then\n                            return quest:event(94)\n                        else\n                            return quest:event(95)\n                        end\n                    elseif progress == 1 then\n                        return quest:progressEvent(98)\n                    elseif progress == 2 then\n                        return quest:event(99)\n                    end\n                end,\n            },\n\n            ['Varun'] =\n            {\n                -- It was found in captures that the dialogue for Varun is not required to progress the quest\n                onTrigger = function(player, npc)\n                    local progress = quest:getVar(player, 'Prog')\n\n                    if progress == 2 then\n                        if quest:getVar(player, 'Option') < 2 then\n                            return quest:progressEvent(100) -- Optional Dialogue that only places once\n                        else\n                            return quest:event(101, 0, xi.item.SHARP_STONE)\n                        end\n                    end\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHas(trade, { { xi.item.SHARP_STONE } }) then\n                        return quest:progressEvent(102, 2100)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [98] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n\n                [100] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Option', 2)\n                end,\n\n                [102] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:confirmTrade()\n                        player:addGil(2100) -- \"Obtained X gil.\" Text is baked into the CS, so gil needs to be given outside of the quest rewards.\n                        quest:setMustZone(player)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.BASTOK_MARKETS] =\n        {\n            ['Ardea'] =\n            {\n                onTrigger = function(player, npc)\n                    local progress = quest:getVar(player, 'Prog')\n\n                    if progress == 0 then\n                        return quest:progressEvent(261)\n                    elseif progress == 1 then\n                        return quest:event(262)\n                    else\n                        return quest:event(263)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [261] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:setVar(player, 'Prog', 1)\n                        player:delKeyItem(xi.keyItem.SHARP_GRAY_STONE) -- Silent\n                        npcUtil.giveCurrency(player, 'gil', 10)\n                    elseif option == 1 then\n                        quest:setVar(player, 'Option', 1)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.WINDURST_WOODS] =\n        {\n            ['Bopa_Greso'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getMustZone(player) then\n                        return quest:event(96)\n                    end\n                end,\n            },\n\n            ['Cha_Lebagta'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getMustZone(player) then\n                        return quest:event(97)\n                    end\n                end,\n            },\n\n            ['Varun'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getMustZone(player) then\n                        return quest:event(103)\n                    else\n                        return quest:event(104):replaceDefault()\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/windurst/SMN_AF1_The_Puppet_Master.lua"]={["Path"]="scripts/quests/windurst/SMN_AF1_The_Puppet_Master.lua",["SHA256"]="db528a10a3364ccba2d98a3d86defeec0975db8b3eb48c481a8f5e8240e06e7d",["Text"]="-----------------------------------\n-- The Puppet Master\n-----------------------------------\n-- Log ID: 2, Quest ID: 81\n-- House of the Hero (_6n2) : !pos -26 -13 260 239\n-- Juroro                   : !pos 32 7 -41 236\n-- Koru-Moru                : !pos -120 -6 124 239\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.WINDURST, xi.quest.id.windurst.THE_PUPPET_MASTER)\n\nquest.reward =\n{\n    fame     = 20,\n    fameArea = xi.fameArea.WINDURST,\n    item     = xi.item.KUKULCANS_STAFF,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getMainLvl() >= xi.settings.main.AF1_QUEST_LEVEL and\n                player:getMainJob() == xi.job.SMN and\n                not quest:getMustZone(player)\n        end,\n\n        [xi.zone.WINDURST_WALLS] =\n        {\n            ['_6n2'] = quest:progressEvent(402),\n\n            onEventFinish =\n            {\n                [402] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.WINDURST_WALLS] =\n        {\n            ['_6n2'] = quest:event(403),\n\n            ['Koru-Moru'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 3 then\n                        return quest:progressEvent(404)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [404] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        quest:setMustZone(player)\n                        xi.quest.setMustZone(player, xi.questLog.WINDURST, xi.quest.id.windurst.CLASS_REUNION)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Juroro'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 0 then\n                        return quest:progressEvent(256, 0, xi.keyItem.TUNING_FORK_OF_EARTH, 0, xi.item.EARTH_PENDULUM):progress() -- Takes priority over quest \"Trial by Earth\"\n                    elseif\n                        questProgress == 1 and\n                        not player:hasItem(xi.item.EARTH_PENDULUM) and\n                        player:getQuestStatus(xi.questLog.BASTOK, xi.quest.id.bastok.TRIAL_BY_EARTH) ~= xi.questStatus.QUEST_ACCEPTED -- Progress is locked as long as the player is on Trial by Earth as confirmed in captures\n                    then\n                        return quest:progressEvent(257, 0, xi.item.EARTH_PENDULUM)\n                    elseif questProgress == 1 then\n                        return quest:event(253, 0, 0, 0, 0, 0, xi.item.EARTH_PENDULUM, 1)\n                    elseif questProgress == 2 then\n                        return quest:progressEvent(258)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [256] = function(player, csid, option, npc)\n                    if npcUtil.giveItem(player, xi.item.EARTH_PENDULUM) then\n                        quest:setVar(player, 'Prog', 1)\n                    end\n                end,\n\n                [257] = function(player, csid, option, npc)\n                    npcUtil.giveItem(player, xi.item.EARTH_PENDULUM)\n                end,\n\n                [258] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 3)\n                end,\n            },\n        },\n\n        [xi.zone.CLOISTER_OF_TREMORS] =\n        {\n            onEventFinish =\n            {\n                [32001] = function(player, csid, option, npc)\n                    if\n                        player:getLocalVar('battlefieldWin') == xi.battlefield.id.PUPPET_MASTER and\n                        quest:getVar(player, 'Prog') == 1\n                    then\n                        quest:setVar(player, 'Prog', 2)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED and\n                not player:hasCompletedQuest(xi.questLog.WINDURST, xi.quest.id.windurst.CLASS_REUNION)\n        end,\n\n        [xi.zone.WINDURST_WALLS] =\n        {\n            ['Koru-Moru'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getMustZone(player) then\n                        return quest:event(405)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/windurst/SMN_I_Can_Hear_a_Rainbow.lua"]={["Path"]="scripts/quests/windurst/SMN_I_Can_Hear_a_Rainbow.lua",["SHA256"]="628eedaf362fa26fb0ab658583c8e17125dcaef113a4e32c4036610ed338fbf7",["Text"]="-----------------------------------\n-- I Can Hear a Rainbow\n-----------------------------------\n-- Log ID: 2, Quest ID: 75\n-----------------------------------\nlocal laTheineID = zones[xi.zone.LA_THEINE_PLATEAU]\n-----------------------------------\nlocal quest = Quest:new(xi.questLog.WINDURST, xi.quest.id.windurst.I_CAN_HEAR_A_RAINBOW)\n\nlocal validWeatherTable =\nset{\n    xi.weather.NONE,\n    xi.weather.HOT_SPELL,\n    xi.weather.HEAT_WAVE,\n    xi.weather.RAIN,\n    xi.weather.SQUALL,\n    xi.weather.DUST_STORM,\n    xi.weather.SAND_STORM,\n    xi.weather.WIND,\n    xi.weather.GALES,\n    xi.weather.SNOW,\n    xi.weather.BLIZZARDS,\n    xi.weather.THUNDER,\n    xi.weather.THUNDERSTORMS,\n}\n\nlocal zoneEventTable =\n{\n    [xi.zone.WEST_RONFAURE         ] = {  51 },\n    [xi.zone.EAST_RONFAURE         ] = {  21 },\n    [xi.zone.NORTH_GUSTABERG       ] = { 244 },\n    [xi.zone.SOUTH_GUSTABERG       ] = { 901 },\n    [xi.zone.WEST_SARUTABARUTA     ] = {  48 },\n    [xi.zone.EAST_SARUTABARUTA     ] = {  50 },\n    [xi.zone.LA_THEINE_PLATEAU     ] = { 123 },\n    [xi.zone.KONSCHTAT_HIGHLANDS   ] = { 104 },\n    [xi.zone.TAHRONGI_CANYON       ] = {  35 },\n    [xi.zone.VALKURM_DUNES         ] = {   3 },\n    [xi.zone.BUBURIMU_PENINSULA    ] = {   3 },\n    [xi.zone.JUGNER_FOREST         ] = {  15 },\n    [xi.zone.BATALLIA_DOWNS        ] = { 901 },\n    [xi.zone.PASHHOW_MARSHLANDS    ] = {  13 },\n    [xi.zone.ROLANBERRY_FIELDS     ] = {   2 },\n    [xi.zone.MERIPHATAUD_MOUNTAINS ] = {  31 },\n    [xi.zone.SAUROMUGUE_CHAMPAIGN  ] = {   3 },\n    [xi.zone.BEAUCEDINE_GLACIER    ] = { 114 },\n    [xi.zone.XARCABARD             ] = {   9 },\n    [xi.zone.YUHTUNGA_JUNGLE       ] = {  11 },\n    [xi.zone.YHOATOR_JUNGLE        ] = {   2 },\n    [xi.zone.THE_SANCTUARY_OF_ZITAH] = {   2 },\n    [xi.zone.EASTERN_ALTEPA_DESERT ] = {   2 },\n    [xi.zone.WESTERN_ALTEPA_DESERT ] = {   2 },\n    [xi.zone.CAPE_TERIGGAN         ] = {   2 },\n}\n\nlocal function handleZoneIn(player, prevZone)\n    if player:hasItem(xi.item.CARBUNCLES_RUBY, xi.inventoryLocation.INVENTORY) then\n        local zone    = player:getZone(true)\n        local weather = zone:getWeather()\n\n        -- Exception: Handle Sunshine weather as weather ID 0 (NONE) for the time being.\n        if weather == xi.weather.SUNSHINE then\n            weather = xi.weather.NONE\n        end\n\n        -- Store weather in a local var just in case weather changes in this few seconds.\n        player:setLocalVar('Weather', weather)\n\n        -- Fetch weather element if it's a valid element.\n        if validWeatherTable[weather] then\n            local lightBitMask = quest:getVar(player, 'Light')\n            local element      = xi.data.element.getWeatherElement(weather)\n            if not utils.mask.getBit(lightBitMask, element) then\n                return zoneEventTable[zone:getID()][1]\n            end\n        end\n    end\nend\n\nlocal function handleEventUpdate(player, csid, option, npc)\n    local weather      = player:getLocalVar('Weather')\n    local lightBitMask = quest:getVar(player, 'Light')\n    local lightCounter = 0\n\n    for bit = 0, 6 do\n        if utils.mask.getBit(lightBitMask, bit) then\n            lightCounter = lightCounter + 1\n        end\n    end\n\n    -- Note: You will only count 6 by triggering the 7th (last) light.\n    -- The client expects a 6 in event update when triggering the last light.\n    if lightCounter == 6 then\n        quest:setVar(player, 'Prog', 1)\n    end\n\n    player:updateEvent(0, 1, weather, lightCounter)\nend\n\nlocal function handleEventFinish(player, csid, option, npc)\n    local weather      = player:getLocalVar('Weather')\n    local element      = xi.data.element.getWeatherElement(weather)\n    local lightBitMask = utils.mask.setBit(quest:getVar(player, 'Light'), element, true)\n\n    quest:setVar(player, 'Light', lightBitMask)\nend\n\nquest.reward =\n{\n    fame     = 20,\n    fameArea = xi.fameArea.WINDURST,\n    keyItem  = xi.keyItem.JOB_GESTURE_SUMMONER,\n    title    = xi.title.RAINBOW_WEAVER,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getMainLvl() >= xi.settings.main.ADVANCED_JOB_LEVEL and\n                player:hasItem(xi.item.CARBUNCLES_RUBY, xi.inventoryLocation.INVENTORY)\n        end,\n\n        [xi.zone.WINDURST_WALLS] =\n        {\n            ['_6n2'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(384, 0, xi.item.CARBUNCLES_RUBY)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [384] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 0\n        end,\n\n        [xi.zone.WINDURST_WALLS] =\n        {\n            ['_6n2'] = quest:event(385, 0, xi.item.CARBUNCLES_RUBY):oncePerZone(),\n        },\n\n        [xi.zone.WEST_RONFAURE] =\n        {\n            onZoneIn = handleZoneIn,\n\n            onEventUpdate =\n            {\n                [51] = handleEventUpdate,\n            },\n\n            onEventFinish =\n            {\n                [51] = handleEventFinish,\n            },\n        },\n\n        [xi.zone.EAST_RONFAURE] =\n        {\n            onZoneIn = handleZoneIn,\n\n            onEventUpdate =\n            {\n                [21] = handleEventUpdate,\n            },\n\n            onEventFinish =\n            {\n                [21] = handleEventFinish,\n            },\n        },\n\n        [xi.zone.NORTH_GUSTABERG] =\n        {\n            onZoneIn = handleZoneIn,\n\n            onEventUpdate =\n            {\n                [244] = handleEventUpdate,\n            },\n\n            onEventFinish =\n            {\n                [244] = handleEventFinish,\n            },\n        },\n\n        [xi.zone.SOUTH_GUSTABERG] =\n        {\n            onZoneIn = handleZoneIn,\n\n            onEventUpdate =\n            {\n                [901] = handleEventUpdate,\n            },\n\n            onEventFinish =\n            {\n                [901] = handleEventFinish,\n            },\n        },\n\n        [xi.zone.WEST_SARUTABARUTA] =\n        {\n            onZoneIn = handleZoneIn,\n\n            onEventUpdate =\n            {\n                [48] = handleEventUpdate,\n            },\n\n            onEventFinish =\n            {\n                [48] = handleEventFinish,\n            },\n        },\n\n        [xi.zone.EAST_SARUTABARUTA] =\n        {\n            onZoneIn = handleZoneIn,\n\n            onEventUpdate =\n            {\n                [50] = handleEventUpdate,\n            },\n\n            onEventFinish =\n            {\n                [50] = handleEventFinish,\n            },\n        },\n\n        [xi.zone.LA_THEINE_PLATEAU] =\n        {\n            onZoneIn = handleZoneIn,\n\n            onEventUpdate =\n            {\n                [123] = handleEventUpdate,\n            },\n\n            onEventFinish =\n            {\n                [123] = handleEventFinish,\n            },\n        },\n\n        [xi.zone.KONSCHTAT_HIGHLANDS] =\n        {\n            onZoneIn = handleZoneIn,\n\n            onEventUpdate =\n            {\n                [104] = handleEventUpdate,\n            },\n\n            onEventFinish =\n            {\n                [104] = handleEventFinish,\n            },\n        },\n\n        [xi.zone.TAHRONGI_CANYON] =\n        {\n            onZoneIn = handleZoneIn,\n\n            onEventUpdate =\n            {\n                [35] = handleEventUpdate,\n            },\n\n            onEventFinish =\n            {\n                [35] = handleEventFinish,\n            },\n        },\n\n        [xi.zone.VALKURM_DUNES] =\n        {\n            onZoneIn = handleZoneIn,\n\n            onEventUpdate =\n            {\n                [3] = handleEventUpdate,\n            },\n\n            onEventFinish =\n            {\n                [3] = handleEventFinish,\n            },\n        },\n\n        [xi.zone.BUBURIMU_PENINSULA] =\n        {\n            onZoneIn = handleZoneIn,\n\n            onEventUpdate =\n            {\n                [3] = handleEventUpdate,\n            },\n\n            onEventFinish =\n            {\n                [3] = handleEventFinish,\n            },\n        },\n\n        [xi.zone.JUGNER_FOREST] =\n        {\n            onZoneIn = handleZoneIn,\n\n            onEventUpdate =\n            {\n                [15] = handleEventUpdate,\n            },\n\n            onEventFinish =\n            {\n                [15] = handleEventFinish,\n            },\n        },\n\n        [xi.zone.BATALLIA_DOWNS] =\n        {\n            onZoneIn = handleZoneIn,\n\n            onEventUpdate =\n            {\n                [901] = handleEventUpdate,\n            },\n\n            onEventFinish =\n            {\n                [901] = handleEventFinish,\n            },\n        },\n\n        [xi.zone.PASHHOW_MARSHLANDS] =\n        {\n            onZoneIn = handleZoneIn,\n\n            onEventUpdate =\n            {\n                [13] = handleEventUpdate,\n            },\n\n            onEventFinish =\n            {\n                [13] = handleEventFinish,\n            },\n        },\n\n        [xi.zone.ROLANBERRY_FIELDS] =\n        {\n            onZoneIn = handleZoneIn,\n\n            onEventUpdate =\n            {\n                [2] = handleEventUpdate,\n            },\n\n            onEventFinish =\n            {\n                [2] = handleEventFinish,\n            },\n        },\n\n        [xi.zone.MERIPHATAUD_MOUNTAINS] =\n        {\n            onZoneIn = handleZoneIn,\n\n            onEventUpdate =\n            {\n                [31] = handleEventUpdate,\n            },\n\n            onEventFinish =\n            {\n                [31] = handleEventFinish,\n            },\n        },\n\n        [xi.zone.SAUROMUGUE_CHAMPAIGN] =\n        {\n            onZoneIn = handleZoneIn,\n\n            onEventUpdate =\n            {\n                [3] = handleEventUpdate,\n            },\n\n            onEventFinish =\n            {\n                [3] = handleEventFinish,\n            },\n        },\n\n        [xi.zone.BEAUCEDINE_GLACIER] =\n        {\n            onZoneIn = handleZoneIn,\n\n            onEventUpdate =\n            {\n                [114] = handleEventUpdate,\n            },\n\n            onEventFinish =\n            {\n                [114] = handleEventFinish,\n            },\n        },\n\n        [xi.zone.XARCABARD] =\n        {\n            onZoneIn = handleZoneIn,\n\n            onEventUpdate =\n            {\n                [9] = handleEventUpdate,\n            },\n\n            onEventFinish =\n            {\n                [9] = handleEventFinish,\n            },\n        },\n\n        [xi.zone.YUHTUNGA_JUNGLE] =\n        {\n            onZoneIn = handleZoneIn,\n\n            onEventUpdate =\n            {\n                [11] = handleEventUpdate,\n            },\n\n            onEventFinish =\n            {\n                [11] = handleEventFinish,\n            },\n        },\n\n        [xi.zone.YHOATOR_JUNGLE] =\n        {\n            onZoneIn = handleZoneIn,\n\n            onEventUpdate =\n            {\n                [2] = handleEventUpdate,\n            },\n\n            onEventFinish =\n            {\n                [2] = handleEventFinish,\n            },\n        },\n\n        [xi.zone.THE_SANCTUARY_OF_ZITAH] =\n        {\n            onZoneIn = handleZoneIn,\n\n            onEventUpdate =\n            {\n                [2] = handleEventUpdate,\n            },\n\n            onEventFinish =\n            {\n                [2] = handleEventFinish,\n            },\n        },\n\n        [xi.zone.EASTERN_ALTEPA_DESERT] =\n        {\n            onZoneIn = handleZoneIn,\n\n            onEventUpdate =\n            {\n                [2] = handleEventUpdate,\n            },\n\n            onEventFinish =\n            {\n                [2] = handleEventFinish,\n            },\n        },\n\n        [xi.zone.WESTERN_ALTEPA_DESERT] =\n        {\n            onZoneIn = handleZoneIn,\n\n            onEventUpdate =\n            {\n                [2] = handleEventUpdate,\n            },\n\n            onEventFinish =\n            {\n                [2] = handleEventFinish,\n            },\n        },\n\n        [xi.zone.CAPE_TERIGGAN] =\n        {\n            onZoneIn = handleZoneIn,\n\n            onEventUpdate =\n            {\n                [2] = handleEventUpdate,\n            },\n\n            onEventFinish =\n            {\n                [2] = handleEventFinish,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 1\n        end,\n\n        [xi.zone.LA_THEINE_PLATEAU] =\n        {\n            ['qm3'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, xi.item.CARBUNCLES_RUBY) then\n                        return quest:progressEvent(124)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [124] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:confirmTrade()\n\n                        -- Unlock SMN job.\n                        player:unlockJob(xi.job.SMN)\n                        player:addSpell(xi.magic.spell.CARBUNCLE)\n                        player:messageSpecial(laTheineID.text.UNLOCK_SUMMONER)\n                        player:messageSpecial(laTheineID.text.UNLOCK_CARBUNCLE)\n\n                        -- Set rainbow to appear.\n                        local rainbow = GetNPCByID(laTheineID.npc.RAINBOW)\n                        if rainbow then\n                            rainbow:setLocalVar('setRainbow', 1)\n                        end\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/windurst/SOB1_Truth_Justice_and_the_Onion_Way.lua"]={["Path"]="scripts/quests/windurst/SOB1_Truth_Justice_and_the_Onion_Way.lua",["SHA256"]="80178fd6b329220a1ad31bf50399fa6d6e2ae93637d2eacae70bf102e96f75cd",["Text"]="-----------------------------------\n-- Truth, Justice, and the Onion Way\n-- Log ID: 2, Quest ID: 36\n-- Kohlo-Lakolo, !pos -26.8 -6 190 240\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.WINDURST, xi.quest.id.windurst.TRUTH_JUSTICE_AND_THE_ONION_WAY)\n\nquest.reward =\n{\n    fame     = 20,\n    fameArea = xi.fameArea.WINDURST,\n    item     = xi.item.JUSTICE_BADGE,\n    title    = xi.title.STAR_ONION_BRIGADE_MEMBER,\n}\n\nquest.sections =\n{\n    -- Section: Quest is available.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.PORT_WINDURST] =\n        {\n            ['Kohlo-Lakolo'] = quest:progressEvent(368), -- Quest starting event.\n\n            onEventFinish =\n            {\n                [368] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest accepeted.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.PORT_WINDURST] =\n        {\n            ['Kohlo-Lakolo'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(371) -- Reminder text.\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, xi.item.RARAB_TAIL) then\n                        return quest:progressEvent(378, 0, xi.item.RARAB_TAIL, xi.item.JUSTICE_BADGE)\n                    end\n                end,\n            },\n\n            -- Reminder text.\n            ['Gomada-Vulmada'] = quest:event(373),\n            ['Papo-Hopo']      = quest:event(372),\n            ['Pichichi']       = quest:event(374),\n            ['Pyo_Nzon']       = quest:event(375),\n            ['Shanruru']       = quest:event(377),\n            ['Yafa_Yaa']       = quest:event(376),\n\n            onEventFinish =\n            {\n                [378] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:confirmTrade()\n                        player:setLocalVar('[2][40]mustZone', 1)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest completed.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED and\n                player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.KNOW_ONES_ONIONS) == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.PORT_WINDURST] =\n        {\n            -- New default texts.\n            ['Gomada-Vulmada'] = quest:event(381):replaceDefault(),\n            ['Papo-Hopo']      = quest:event(380):replaceDefault(),\n            ['Pichichi']       = quest:event(385):replaceDefault(),\n            ['Pyo_Nzon']       = quest:event(382):replaceDefault(),\n            ['Shanruru']       = quest:event(384):replaceDefault(),\n            ['Yafa_Yaa']       = quest:event(383):replaceDefault(),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/windurst/SOB2_Know_Ones_Onions.lua"]={["Path"]="scripts/quests/windurst/SOB2_Know_Ones_Onions.lua",["SHA256"]="e18d820ff6ed8de083b12bdc9c55082d1bdf0c40a8f7ed8d2f4e15c22e796bca",["Text"]="-----------------------------------\n-- Know One's Onions\n--\n-- Kohlo-Lakolo, !pos -26.8 -6 190 240\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.WINDURST, xi.quest.id.windurst.KNOW_ONES_ONIONS)\n\nquest.reward =\n{\n    fame     = 20,\n    fameArea = xi.fameArea.WINDURST,\n    item     = xi.item.SCROLL_OF_BLAZE_SPIKES,\n    title    = xi.title.SOB_SUPER_HERO,\n}\n\n-- NOTE\n-- This quest has a peculiarity. You can \"miss\" the events of the quest by arriving \"late\".\n-- You can be late/meet the cutoff mid-quest or start already late.\n-- This effectively means the quest branches off.\n\n-- The cutoff/timer/event that makes it change is currently unkonwn.\n\n-- For now, and becouse of the in-game lore, it's going to be assumed that the cutoff is based on Windurst rank.\n-- There is a testimony that \"supports\" this theory, stating that the cutoff is based on \"Old Ring\" Key item obtention.\n-- Old Ring is a temporal KI, so checking for it wouldn't be a lasting solution.\n\nquest.sections =\n{\n    -- Section: Quest is available.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getMainLvl() >= 5 and\n                player:hasCompletedQuest(xi.questLog.WINDURST, xi.quest.id.windurst.TRUTH_JUSTICE_AND_THE_ONION_WAY)\n        end,\n\n        [xi.zone.PORT_WINDURST] =\n        {\n            ['Kohlo-Lakolo'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        player:getMainLvl() >= 5 and\n                        not quest:getMustZone(player)\n                    then\n                        if player:getRank(xi.nation.WINDURST) < 3 then\n                            return quest:progressEvent(391, 0, xi.item.WILD_ONION) -- Quest starting event. (In time)\n                        else\n                            return quest:progressEvent(388, 0, xi.item.WILD_ONION) -- Quest starting event. (Missed action)\n                        end\n                    else\n                        return quest:event(379) -- Default text.\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [388] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n\n                [391] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest accepeted in time.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n                vars.Prog == 1 and\n                player:getRank(xi.nation.WINDURST) < 3\n        end,\n\n        [xi.zone.PORT_WINDURST] =\n        {\n            ['Kohlo-Lakolo'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(392, 0, xi.item.WILD_ONION) -- Reminder text if you are still in time.\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, { { xi.item.WILD_ONION, 4 } }) then\n                        return quest:progressEvent(398, 0, xi.item.WILD_ONION) -- Trade in time. Quest goes on.\n                    end\n                end,\n            },\n\n            ['Gomada-Vulmada'] = quest:event(394),\n            ['Papo-Hopo']      = quest:event(393),\n            ['Pichichi']       = quest:event(395),\n            ['Pyo_Nzon']       = quest:event(396),\n            ['Yafa_Yaa']       = quest:event(397),\n\n            onEventFinish =\n            {\n                [398] = function(player, csid, option, npc)\n                    player:confirmTrade()\n                    quest:setVar(player, 'Prog', 2)\n                end,\n            },\n        },\n    },\n\n    -- Section: Trade performed in time.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n                vars.Prog == 2 and\n                player:getRank(xi.nation.WINDURST) < 3\n        end,\n\n        [xi.zone.PORT_WINDURST] =\n        {\n            ['Gomada-Vulmada'] = quest:event(394),\n            ['Kohlo-Lakolo']   = quest:event(399, 0, xi.item.WILD_ONION),\n            ['Papo-Hopo']      = quest:event(393),\n            ['Pichichi']       = quest:event(395),\n            ['Pyo_Nzon']       = quest:event(396),\n            ['Yafa_Yaa']       = quest:event(397),\n        },\n\n        [xi.zone.WINDURST_WALLS] =\n        {\n            ['_6n2'] = quest:progressEvent(288, 0, xi.item.WILD_ONION),\n\n            onEventFinish =\n            {\n                [288] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 3)\n                end,\n            },\n        },\n    },\n\n    -- Section: Expedition complete. End quest.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n                vars.Prog == 3\n        end,\n\n        [xi.zone.PORT_WINDURST] =\n        {\n            ['Gomada-Vulmada'] = quest:event(404),\n            ['Kohlo-Lakolo']   = quest:progressEvent(400),\n            ['Papo-Hopo']      = quest:event(402),\n            ['Pichichi']       = quest:event(410),\n            ['Pyo_Nzon']       = quest:event(408),\n            ['Yafa_Yaa']       = quest:event(406),\n\n            onEventFinish =\n            {\n                [400] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:setLocalVar('[2][41]mustZone', 1)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest accepted. You are late at any step of the process, except very last step.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n                vars.Prog < 3 and\n                player:getRank(xi.nation.WINDURST) >= 3\n        end,\n\n        [xi.zone.PORT_WINDURST] =\n        {\n            ['Kohlo-Lakolo'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 0 then\n                        return quest:event(389, 0, xi.item.WILD_ONION) -- Reminder text: Started quest late.\n                    elseif quest:getVar(player, 'Prog') == 1 then\n                        return quest:event(387, 0, xi.item.WILD_ONION) -- Reminder text: In time for introduction but late before trade is done.\n                    elseif quest:getVar(player, 'Prog') == 2 then\n                        return quest:event(386)                         -- Reminder text: Late after trade. Quest Complete.\n                    end\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, { { xi.item.WILD_ONION, 4 } }) then\n                        return quest:progressEvent(390) -- Quest Complete.\n                    end\n                end,\n            },\n\n            ['Gomada-Vulmada'] = quest:event(405),\n            ['Papo-Hopo']      = quest:event(403),\n            ['Pichichi']       = quest:event(411),\n            ['Pyo_Nzon']       = quest:event(409),\n            ['Shanruru']       = quest:event(412),\n            ['Yafa_Yaa']       = quest:event(407),\n\n            onEventFinish =\n            {\n                [386] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:setLocalVar('[2][41]mustZone', 1)\n                    end\n                end,\n\n                [390] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:confirmTrade()\n                        player:setLocalVar('[2][41]mustZone', 1)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest completed.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED and\n                player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.INSPECTORS_GADGET) == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.PORT_WINDURST] =\n        {\n            -- New default texts.\n            ['Gomada-Vulmada'] = quest:event(405):replaceDefault(),\n            ['Papo-Hopo']      = quest:event(403):replaceDefault(),\n            ['Pichichi']       = quest:event(411):replaceDefault(),\n            ['Pyo_Nzon']       = quest:event(409):replaceDefault(),\n            ['Shanruru']       = quest:event(412):replaceDefault(),\n            ['Yafa_Yaa']       = quest:event(407):replaceDefault(),\n        },\n    },\n}\n\nreturn quest\n"}};
